INSERT OR IGNORE INTO deity_profiles(
    entity_id,deity_class,pantheon_or_family,rank_or_status,domains_json,powers_json,limitations_json,appearance_json,symbols_json,cult_summary,final_fate_summary
) VALUES
('hero.greek.heracles','Divinised hero','Son of Zeus and Alcmena; husband of Hebe after his apotheosis',NULL,'["strength", "averting evils"]','[]','[]','{}','[]',NULL,'Raised from the pyre on Mount Oeta to the gods; reconciled with Hera.'),
('deity.greek.atlas','Titan','Son of Iapetus',NULL,'["holding up the sky"]','[]','[]','{}','[]',NULL,NULL),
('deity.greek.hebe','Goddess of youth','Daughter of Zeus and Hera; wife of the deified Heracles',NULL,'["youth"]','[]','[]','{}','[]',NULL,NULL),
('deity.greek.eros','God of love','Son of Aphrodite (in the Argonautica)',NULL,'["love", "desire"]','[]','[]','{}','[]',NULL,NULL),
('deity.norse.vidar','Æsir god','Son of Odin and the giantess Gríðr',NULL,'["vengeance", "silence"]','[]','[]','{}','[]',NULL,'Survives Ragnarök and dwells at Iðavöllr.'),
('deity.welsh.arawn','Otherworld king','King of Annwn',NULL,'["the Otherworld", "hunting hounds"]','[]','[]','{}','[]',NULL,NULL);

INSERT OR IGNORE INTO creature_profiles(
    entity_id,creature_class,appearance_json,abilities_json,weaknesses_json,habitat_summary,origin_summary,fate_summary
) VALUES
('creature.greek.medusa','GORGON','{"hair": "scales of dragons", "wings": "golden", "tusks": "like swine"}','["turns those who look at her to stone"]','[]','By the stream of Ocean, with her sisters Stheno and Euryale','Daughter of Phorcus and Ceto.','Beheaded by Perseus; her head set in Athena''s aegis.'),
('creature.greek.graeae','CRONE_SISTERS','{"eyes": 1, "teeth": 1}','["share a single eye and tooth"]','[]','Near the Gorgons, at the edge of the world','Daughters of Phorcus and Ceto, sisters of the Gorgons.','Their eye and tooth are returned after they show Perseus the way.'),
('creature.greek.pegasus','WINGED_HORSE','{}','["flight"]','[]','Born at the stream of Ocean','Offspring of Poseidon and Medusa.','Later tamed by Bellerophon (Library 2.3.2).'),
('creature.greek.nemean_lion','LION','{}','["invulnerable to weapons"]','[]','A cave with two mouths near Nemea','Offspring of Typhon.','Strangled by Heracles, who wore its skin.'),
('creature.greek.lernaean_hydra','WATER_SERPENT','{"heads": 9}','["two heads grow when one is cut off", "poisonous gall"]','[]','The swamp of Lerna by the spring Amymone','Bred in the swamp of Lerna.','Killed by Heracles; its immortal head buried under a rock and its gall used to poison his arrows.'),
('creature.greek.geryon','TRIPLE_BODIED_GIANT','{"bodies": 3, "heads": 3}','["three bodies joined at the waist"]','[]','The island Erytheia near Ocean','Son of Chrysaor and Callirrhoe, daughter of Ocean.','Shot by Heracles beside the river Anthemus.'),
('creature.greek.cerberus','HELLHOUND','{"heads": 3, "tail": "serpent"}','["guards the house of Hades"]','[]','The gates of Hades','Offspring of Typhon and Echidna.','Shown to Eurystheus and carried back to Hades.'),
('creature.greek.nessus','CENTAUR','{}','["ferries travellers across the Evenus"]','[]','The river Evenus in Aetolia','One of the centaurs, said to have received the ferry from the gods for his righteousness.','Shot through the heart by Heracles.'),
('creature.greek.harpies','WINGED_SNATCHERS','{}','["swoop down to snatch food"]','[]','Thrace; afterwards a cave in Crete','Called ''the hounds of great Zeus'' by Iris.','Spared at Iris''s word and never to return to Phineus.'),
('creature.greek.talos','BRONZE_GIANT','{"body": "bronze"}','["hurls rocks", "invulnerable save at the ankle"]','[]','Crete','Last of the bronze race, given by Zeus to Europa as guardian of Crete.','Grazes his ankle on a rock and bleeds to death under Medea''s evil eye.'),
('creature.norse.surtr','FIRE_GIANT','{}','["a sword brighter than the sun", "flings fire over the world"]','[]','Muspell, the realm of fire','Guardian of Muspell''s border since the beginning.','Burns the world at Ragnarök.'),
('creature.norse.garm','HELLHOUND','{}','["the worst of monsters"]','[]','Gnipahellir','Bound before the cave Gnipahellir.','Kills and is killed by Týr.'),
('creature.norse.fafnir','DRAGON','{}','["breathes venom", "wears the helm of terror"]','[]','Gnitaheiðr, lying on the hoard','A man, son of Hreiðmarr, who took the shape of a serpent out of greed for the gold.','Stabbed from below by Sigurðr with Gram.'),
('creature.norse.grani','HORSE','{}','["swims back to no shore but his master''s", "carries the hoard"]','[]','The meadows of King Hjálprekr','Of the kin of Sleipnir, Odin''s horse.','Carries Sigurðr through Brynhildr''s fire.'),
('creature.irish.donn_cuailnge','BULL','{}','["fifty boys could play on his back", "his bellowing heard across the province"]','[]','Cúailnge in Ulster','Counted among the great bulls of Ireland; in other tales a reborn swineherd.','Kills Finnbennach and dies at Druim Tairb when his heart breaks.'),
('creature.irish.finnbennach','BULL','{}','["the greatest bull of Connacht"]','[]','Ailill''s herds at Cruachan','Calved among Medb''s cows.','Torn apart by the Brown Bull, its pieces scattered across Ireland.');

INSERT OR IGNORE INTO artifact_profiles(
    entity_id,artifact_type,material_json,appearance_json,abilities_json,limitations_json,usage_conditions_json,creation_summary,fate_summary
) VALUES
('artifact.greek.argo','SHIP','["pine", "Dodonian oak"]','{}','["a beam that speaks with a human voice"]','[]','[]','Built by Argus with Athena''s guidance at Pagasae.','Returns to Pagasae with the fleece.'),
('artifact.greek.golden_fleece','FLEECE','["gold"]','{}','["shines like lightning"]','[]','[]','Fleece of the ram that carried Phrixus, sacrificed to Zeus and hung on an oak in the grove of Ares.','Carried off by Jason with Medea''s help.'),
('artifact.norse.naglfar','SHIP','["the untrimmed nails of the dead"]','{}','["floats loose in the flood of Ragnarök"]','[]','[]','Built from the nails of dead men; hence, says Snorri, no one should die with untrimmed nails.','Steered by Hrymr to the battle at Vígríðr.'),
('artifact.norse.andvaranaut','RING','["gold"]','{}','["multiplies wealth (in Snorri)", "carries Andvari''s curse"]','[]','[]','Kept back by Andvari from his hoard until Loki took it.','Given by Sigurðr to Brynhildr, taken back in Gunnarr''s shape and given to Guðrún.'),
('artifact.welsh.cauldron_of_rebirth','CAULDRON','["metal"]','{}','["a slain man cast into it rises alive but cannot speak"]','[]','[]','Brought out of a lake in Ireland by Llassar Llaes Gyfnewid and his wife.','Burst into four pieces by Efnysien.');

