    entity_id,text_type,original_language_id,attributed_author,compiler,composition_period,earliest_extant_witness,chapter_structure,repository,shelfmark,copyright_status,summary
) VALUES
('text.norse.volsunga_saga','SAGA','lang.non',NULL,NULL,'13th century (Iceland)','Copenhagen, Royal Library, NKS 1824 b 4to (c. 1400)','43 chapters in the Morris and Magnússon numbering',NULL,NULL,'Medieval text in the public domain','The Völsung line from Sigi to Sigurðr''s death and Guðrún''s later fate.'),
('text.irish.tain_bo_cuailnge','SAGA','lang.gle',NULL,NULL,'Recension I (Lebor na hUidre) and Recension II (Book of Leinster), 11th–12th century manuscripts','Book of Leinster, Dublin, Trinity College MS 1339 (c. 1160)','Prose saga with verse passages',NULL,NULL,'Medieval text in the public domain','The muster of Medb, Cú Chulainn''s defence of the fords, Fer Diad, the rising of Ulster and the fight of the bulls.'),
('text.welsh.four_branches','PROSE_TALES','lang.wlm',NULL,NULL,'Composition c. 11th–12th century; dating debated','White Book of Rhydderch (NLW Peniarth MSS 4–5, c. 1350) and Red Book of Hergest (Oxford, Jesus College MS 111, c. 1400)','Four branches',NULL,NULL,'Medieval text in the public domain','Pwyll and Rhiannon, Branwen and Bendigeidfran, Manawydan and the enchantment of Dyfed, Math, Gwydion, Lleu and Blodeuedd.');

INSERT OR IGNORE INTO place_profiles(
