('place.welsh.annwn','OTHERWORLD',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'MYTHICAL','TEXTUAL');

INSERT OR IGNORE INTO claims(
    id,subject_id,predicate,object_entity_id,object_literal,object_datatype,statement,variant_group,claim_status,confidence,confidence_level,review_status,assertion_scope,knowledge_layer,tradition_scope,temporal_scope,research_notes,created_at
) VALUES
('claim.v0340.perseus.01','hero.greek.acrisius','NARRATIVE_ACTION',NULL,'imprisons Danaë in a bronze chamber after the oracle','string','Warned by an oracle that his daughter''s son would kill him, Acrisius imprisons Danaë in an underground bronze chamber, where Zeus visits her as a shower of gold and she bears Perseus.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.02','hero.greek.danae','NARRATIVE_ACTION',NULL,'is cast into the sea in a chest with Perseus and rescued by Dictys','string','Acrisius casts Danaë and the infant Perseus into the sea in a chest, which washes ashore on Seriphos, where Dictys takes them in and rears the boy.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.03','person.greek.polydectes','NARRATIVE_ACTION','hero.greek.perseus',NULL,NULL,'Wanting Danaë, King Polydectes tricks Perseus at a feast for bridal gifts into undertaking to bring him the Gorgon''s head.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.04','hero.greek.perseus','NARRATIVE_ACTION','creature.greek.graeae',NULL,NULL,'Guided by Hermes and Athena, Perseus seizes the single eye and tooth shared by the three Phorcides and returns them only when they show him the way to the nymphs.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.05','hero.greek.perseus','NARRATIVE_ACTION',NULL,'receives winged sandals, the kibisis and the cap of Hades','string','The nymphs give Perseus winged sandals, the kibisis wallet and the cap of Hades, and Hermes gives him an adamantine sickle, with which he flies to the Gorgons at Ocean.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.06','creature.greek.medusa','NARRATIVE_ACTION',NULL,'is found asleep with her immortal sisters by Ocean','string','Perseus finds the three Gorgons, Stheno, Euryale and the mortal Medusa, asleep by Ocean; the Library describes their dragon-scaled heads, tusks, bronze hands and golden wings and their petrifying gaze.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.07','hero.greek.perseus','NARRATIVE_ACTION','creature.greek.medusa',NULL,NULL,'Looking at Medusa''s reflection in a bronze shield with Athena guiding his hand, Perseus beheads her; Pegasus and Chrysaor spring from her neck, and the cap of Hades hides him from her pursuing sisters.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.08','hero.greek.perseus','NARRATIVE_ACTION','hero.greek.andromeda',NULL,NULL,'In Ethiopia Perseus finds Andromeda exposed to a sea monster sent by Poseidon after Cassiepea''s boast, wins the oath of her parents that she will be his wife, kills the monster and frees her.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.09','hero.greek.perseus','NARRATIVE_ACTION',NULL,'petrifies Phineus and his fellow conspirators','string','When Phineus, Andromeda''s former betrothed, plots against him, Perseus shows the Gorgon''s head and turns Phineus and his fellow conspirators to stone.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.10','hero.greek.perseus','NARRATIVE_ACTION','person.greek.polydectes',NULL,NULL,'Finding Danaë and Dictys driven to the altars by Polydectes''s violence, Perseus turns Polydectes and his friends to stone with the Gorgon''s head and makes Dictys king of Seriphos.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.11','deity.greek.athena','NARRATIVE_ACTION',NULL,'sets the Gorgon''s head in the middle of her aegis','string','Perseus returns the sandals, wallet and cap through Hermes to the nymphs and gives the Gorgon''s head to Athena, who sets it in the middle of her aegis.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.perseus.12','hero.greek.perseus','NARRATIVE_ACTION','hero.greek.acrisius',NULL,NULL,'At funeral games in Larissa Perseus''s discus strikes and kills Acrisius, fulfilling the oracle; ashamed to claim Argos, Perseus exchanges it for Tiryns and fortifies Midea and Mycenae.','v0340.perseus','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.01','deity.greek.hera','NARRATIVE_ACTION','hero.greek.eurystheus',NULL,NULL,'When Zeus declares that the descendant of Perseus born that day will reign over Mycenae, Hera delays Alcmena''s delivery and has Eurystheus born first as a seven-month child.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.02','deity.greek.zeus','NARRATIVE_ACTION','hero.greek.alcmena',NULL,NULL,'On the night before Amphitryon''s return from the Taphian war, Zeus in his likeness lies with Alcmena and makes the night threefold; Alcmena bears Heracles to Zeus and Iphicles to Amphitryon.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.03','hero.greek.heracles','NARRATIVE_ACTION',NULL,'strangles in his cradle the serpents sent by Hera','string','At eight months old Heracles strangles two huge serpents sent by Hera to his bed, while Iphicles cries out; Pherecydes says instead that Amphitryon put them there to learn which child was his.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.04','hero.greek.heracles','NARRATIVE_ACTION',NULL,'kills his lyre teacher Linus and is acquitted','string','Taught chariot-driving, wrestling, archery, fighting in arms and the lyre by famous teachers, Heracles kills Linus with the lyre, is acquitted under the law of Rhadamanthys, and is sent to the cattle farm.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.05','hero.greek.heracles','NARRATIVE_ACTION',NULL,'kills the lion of Cithaeron','string','At eighteen Heracles, entertained fifty days by Thespius, kills the lion of Cithaeron and thereafter wears its skin and gaping jaws.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.06','hero.greek.heracles','NARRATIVE_ACTION',NULL,'defeats the Minyans and marries Megara','string','Heracles mutilates the heralds of Erginus who come for the Minyan tribute, defeats the Minyans for Thebes, in which war Amphitryon dies, and receives Megara from Creon and arms from the gods.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.07','hero.greek.heracles','NARRATIVE_ACTION',NULL,'is sent by the Delphic oracle to serve Eurystheus','string','Driven mad by Hera, Heracles throws his own children and two of Iphicles''s into the fire; the Pythia names him Heracles and orders him to serve Eurystheus at Tiryns for twelve years and perform the labours, promising immortality.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.08','hero.greek.heracles','NARRATIVE_ACTION','creature.greek.nemean_lion',NULL,NULL,'For his first labour Heracles chokes the invulnerable Nemean lion in a two-mouthed cave, sacrifices with Molorchus at Cleonae, and so frightens Eurystheus that the king hides in a bronze jar and sends orders by herald.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.09','hero.greek.heracles','NARRATIVE_ACTION','creature.greek.lernaean_hydra',NULL,NULL,'With Iolaus searing each severed neck, Heracles kills the nine-headed Lernaean hydra, buries its immortal head under a rock and poisons his arrows with its gall; Eurystheus refuses to count the labour because he had help.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.10','hero.greek.heracles','NARRATIVE_ACTION',NULL,'captures the golden-horned hind of Artemis after a year''s hunt','string','After hunting it for a year, Heracles captures the golden-horned Cerynitian hind sacred to Artemis at the river Ladon and appeases Artemis and Apollo by blaming Eurystheus.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.11','hero.greek.heracles','NARRATIVE_ACTION',NULL,'captures the Erymanthian boar after the fight with the centaurs','string','On the way to the Erymanthian boar Heracles opens the centaurs'' wine jar at Pholus''s cave, fights the centaurs and accidentally wounds Chiron with a hydra-poisoned arrow; he then snares the boar in deep snow and brings it alive to Mycenae.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.12','hero.greek.heracles','NARRATIVE_ACTION',NULL,'cleanses Augeas''s cattle-yard by diverting two rivers','string','Heracles cleanses the cattle-yard of Augeas in one day by diverting the rivers Alpheus and Peneus through it; Augeas refuses the promised tenth of his cattle and Eurystheus refuses to count the labour as done for hire.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_1.13','hero.greek.heracles','NARRATIVE_ACTION',NULL,'drives off the Stymphalian birds with Athena''s castanets','string','With bronze castanets made by Hephaestus and given by Athena, Heracles frightens the Stymphalian birds out of their wood and shoots them down.','v0340.heracles_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.01','hero.greek.heracles','NARRATIVE_ACTION',NULL,'captures the Cretan bull','string','For his seventh labour Heracles captures the Cretan bull, said to be either Europa''s bull or the bull Minos failed to sacrifice to Poseidon, and brings it to Eurystheus, who lets it go to roam to Marathon.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.02','hero.greek.heracles','NARRATIVE_ACTION',NULL,'brings the man-eating mares of Diomedes to Mycenae','string','Heracles drives off the man-eating mares of the Thracian king Diomedes, kills Diomedes, founds Abdera at the grave of Abderus whom the mares devoured, and brings the mares to Eurystheus.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.03','hero.greek.heracles','NARRATIVE_ACTION','hero.greek.hippolyte',NULL,NULL,'Hippolyte promises Heracles the belt of Ares, but Hera in the guise of an Amazon raises the cry that the queen is being abducted; Heracles, suspecting treachery, kills Hippolyte and takes the belt.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.04','hero.greek.heracles','NARRATIVE_ACTION',NULL,'saves Hesione at Troy and is cheated by Laomedon','string','On the way back from the Amazons Heracles kills the sea monster sent by Poseidon against Troy and saves Hesione for the promised mares of Zeus, but Laomedon refuses payment and Heracles vows war.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.05','deity.greek.helios','NARRATIVE_ACTION',NULL,'lends Heracles his golden goblet to cross Ocean','string','On his way to Geryon Heracles sets up pillars at the bounds of Europe and Libya and, when he bends his bow at the scorching Sun, Helios in admiration lends him the golden goblet in which he crosses Ocean.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.06','hero.greek.heracles','NARRATIVE_ACTION','creature.greek.geryon',NULL,NULL,'On Erytheia Heracles clubs the dog Orthus and the herdsman Eurytion, shoots Geryon by the river Anthemus, and ships the red cattle in the Sun''s goblet to Tartessus.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.07','hero.greek.heracles','NARRATIVE_ACTION',NULL,'drives Geryon''s cattle back to Greece','string','Driving Geryon''s cattle through Europe Heracles kills Ialebion, Dercynus and Eryx; Hera''s gadfly scatters the herd in Thrace, and after eight years and a month Eurystheus imposes two more labours in place of the two he rejected.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.08','hero.greek.heracles','NARRATIVE_ACTION',NULL,'wrestles Nereus and kills Antaeus','string','Seeking the Hesperides, Heracles holds the shape-shifting Nereus until he reveals the way, and in Libya lifts Antaeus, who draws strength from his mother Earth, off the ground and crushes him.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.09','hero.greek.heracles','NARRATIVE_ACTION','deity.greek.prometheus',NULL,NULL,'Heracles bursts his bonds at the altar of Busiris in Egypt, then in the Caucasus shoots the eagle that devours Prometheus''s liver and frees him, receiving his advice to send Atlas for the apples.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.10','deity.greek.atlas','NARRATIVE_ACTION',NULL,'is tricked into taking back the sky','string','Atlas fetches three golden apples of the Hesperides while Heracles holds the sky, wants to deliver them himself, and is tricked into taking back the sky when Heracles asks to put a pad on his head.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.11','hero.greek.heracles','NARRATIVE_ACTION',NULL,'descends to Hades and frees Theseus','string','Initiated at Eleusis, Heracles descends at Taenarum, meets the shades of Meleager and Medusa, raises Theseus from the seat of forgetfulness but must leave Pirithous, and wrestles the herdsman Menoetes.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_2.12','hero.greek.heracles','NARRATIVE_ACTION','creature.greek.cerberus',NULL,NULL,'Permitted by Pluto to take Cerberus without weapons, Heracles masters the hound with his arms at the gates of Acheron, brings it up through Troezen to show Eurystheus, and returns it to Hades, completing the twelve labours.','v0340.heracles_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.01','hero.greek.heracles','NARRATIVE_ACTION','hero.greek.iole',NULL,NULL,'Heracles outshoots Eurytus and his sons at Oechalia but is refused Iole, Eurytus fearing he would kill his children again; only Iphitus speaks for him.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.02','hero.greek.heracles','NARRATIVE_ACTION',NULL,'kills Iphitus by throwing him from the walls of Tiryns','string','When Iphitus, who doubts that Heracles stole Eurytus''s cattle, comes to him at Tiryns, Heracles in a renewed fit of madness throws him from the walls, and is afflicted with disease despite purification by Deiphobus.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.03','hero.greek.heracles','NARRATIVE_ACTION','deity.greek.apollo',NULL,NULL,'Refused an oracle at Delphi, Heracles tries to carry off the tripod and fights Apollo until Zeus parts them with a thunderbolt; the oracle orders him sold into three years'' servitude, and Hermes sells him to Omphale.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.04','hero.greek.heracles','NARRATIVE_ACTION','hero.greek.omphale',NULL,NULL,'Serving Omphale, Heracles binds the Cercopes near Ephesus, kills Syleus who forced strangers to dig his vineyard, and buries Icarus; the Argonauts'' voyage falls in these years.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.05','hero.greek.heracles','NARRATIVE_ACTION',NULL,'sacks Troy and kills Laomedon','string','Heracles sacks Troy, spares Telamon who builds an altar to ''Heracles the Glorious Victor'', shoots Laomedon and his sons, and lets Hesione ransom her brother Podarces with her veil, who is thereafter called Priam.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.06','hero.greek.heracles','NARRATIVE_ACTION',NULL,'fights beside the gods against the giants at Phlegra','string','After Hera''s storms drive him to Cos, Heracles is brought by Athena to Phlegra to fight beside the gods against the giants, then takes Elis, kills Augeas and celebrates the Olympian games, and sacks Pylos sparing only Nestor.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.07','hero.greek.heracles','NARRATIVE_ACTION','hero.greek.deianira',NULL,NULL,'To win Deianira at Calydon, Heracles wrestles the river god Achelous in the form of a bull and breaks off his horn, which Achelous redeems with the horn of Amalthea.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.08','creature.greek.nessus','NARRATIVE_ACTION','hero.greek.deianira',NULL,NULL,'Shot by Heracles at the river Evenus for assaulting Deianira, the dying centaur Nessus tells her to keep his blood from the wound as a love charm, which she does.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.09','hero.greek.heracles','NARRATIVE_ACTION','hero.greek.iole',NULL,NULL,'Heracles musters an army from Trachis, sacks Oechalia, kills Eurytus and his sons and takes Iole captive, then sends Lichas to fetch fine raiment for a sacrifice to Cenaean Zeus.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.10','hero.greek.deianira','NARRATIVE_ACTION','hero.greek.heracles',NULL,NULL,'Believing Nessus''s blood a love charm, Deianira smears a tunic with it; the hydra''s poison eats Heracles''s flesh as he sacrifices, he hurls Lichas into the sea, and Deianira hangs herself.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.11','hero.greek.heracles','NARRATIVE_ACTION',NULL,'is borne up to heaven from the pyre on Mount Oeta','string','Heracles charges Hyllus to marry Iole, mounts a pyre on Mount Oeta which Poeas kindles and receives his bow for it, and is borne up to heaven by a cloud with a peal of thunder.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.heracles_3.12','hero.greek.heracles','NARRATIVE_ACTION','deity.greek.hebe',NULL,NULL,'Made immortal, Heracles is reconciled with Hera and marries Hebe; on earth his sons find refuge at the Athenian altar of Mercy, and Hyllus kills the fleeing Eurystheus near the Scironian cliffs.','v0340.heracles_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Pseudo-Apollodorus, Library (Frazer translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.01','hero.greek.pelias','NARRATIVE_ACTION','hero.greek.jason',NULL,NULL,'Warned by an oracle against a man with one sandal, Pelias sees Jason arrive at his sacrifice having lost a sandal in the river Anaurus and sends him on the perilous voyage for the golden fleece.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.02','artifact.greek.argo','NARRATIVE_ACTION',NULL,'is built under Athena''s direction and manned by the Argonauts','string','The Argo is built by Argus under Athena''s direction with a speaking beam of Dodonian oak, and some fifty heroes including Orpheus, Heracles, the Dioscuri and the sons of Boreas gather to sail with Jason.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.03','hero.greek.orpheus','NARRATIVE_ACTION',NULL,'calms the heroes'' quarrel with a song of the world''s beginning','string','After Heracles refuses the leadership and Jason is chosen, Orpheus calms a quarrel between Idas and Idmon at the parting feast with a song of how earth, heaven and sea were parted and Zeus came to rule.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.04','hero.greek.hypsipyle','NARRATIVE_ACTION','hero.greek.jason',NULL,NULL,'On Lemnos, whose women had killed their menfolk, Queen Hypsipyle receives Jason and the Argonauts, who linger until Heracles rebukes them back to the ship.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.05','hero.greek.jason','NARRATIVE_ACTION',NULL,'kills King Cyzicus in a night battle of mistaken identity','string','Driven back by night to the land of the Doliones, the Argonauts fight their hosts unrecognised in the dark and Jason kills King Cyzicus, whose queen Cleite hangs herself; the storm abates only after sacrifice to Rhea.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.06','hero.greek.hylas','NARRATIVE_ACTION',NULL,'is drawn into a spring by a water-nymph','string','In Mysia a water-nymph draws Hylas into a spring; Heracles and Polyphemus search for him and are left behind, and the sea god Glaucus declares that it is Zeus''s will that Heracles return to his labours.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.07','hero.greek.polydeuces','NARRATIVE_ACTION',NULL,'kills the boxer-king Amycus','string','Among the Bebrycians, whose king Amycus forces every stranger to box with him, Polydeuces kills Amycus with a blow above the ear and the Argonauts rout his people.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.08','hero.greek.phineus','NARRATIVE_ACTION','creature.greek.harpies',NULL,NULL,'The sons of Boreas drive the Harpies from the blind seer Phineus until Iris swears by the Styx that they will not return, and Phineus in gratitude tells the Argonauts their route and how to pass the Clashing Rocks.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.09','deity.greek.athena','NARRATIVE_ACTION','artifact.greek.argo',NULL,NULL,'After a dove passes the Clashing Rocks losing only tail feathers, Athena holds back a rock with one hand and thrusts the Argo through with the other, and the rocks are fixed in place for ever.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.10','deity.greek.apollo','NARRATIVE_ACTION',NULL,'appears to the Argonauts at dawn on Thynias','string','On the island of Thynias the Argonauts see Apollo pass at dawn on his way from Lycia to the Hyperboreans and build him an altar; in the land of the Mariandyni the seer Idmon is killed by a boar and the helmsman Tiphys dies of sickness.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.11','hero.greek.jason','NARRATIVE_ACTION',NULL,'meets the shipwrecked sons of Phrixus on the island of Ares','string','On the island of Ares the Argonauts roof the ship with their shields against birds that shoot their feathers, and rescue the shipwrecked sons of Phrixus, who agree to guide them to Colchis.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_1.12','hero.greek.jason','NARRATIVE_ACTION',NULL,'arrives by night in the river Phasis in Colchis','string','Passing the Caucasus, where they hear Prometheus''s cries as the eagle flies to him, the Argonauts enter the Phasis by night, Jason pours libations to Earth and the gods of the land, and the ship is hidden in the reeds near the grove of the fleece.','v0340.argo_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.01','deity.greek.aphrodite','NARRATIVE_ACTION','deity.greek.eros',NULL,NULL,'At the request of Hera and Athena, Aphrodite promises Eros the golden ball Zeus played with as a child if he will shoot Medea with love for Jason.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.02','deity.greek.eros','NARRATIVE_ACTION','hero.greek.medea',NULL,NULL,'In Aeetes''s palace, as Chalciope welcomes her sons, Eros crouching at Jason''s feet shoots Medea with an arrow that burns in her heart like fire.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.03','hero.greek.aeetes','NARRATIVE_ACTION','hero.greek.jason',NULL,NULL,'Aeetes, suspecting a plot against his throne, sets Jason the trial of yoking fire-breathing bronze-footed bulls, ploughing the field of Ares, sowing a serpent''s teeth and slaying the armed men who spring from them, all in one day.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.04','hero.greek.medea','NARRATIVE_ACTION',NULL,'resolves after a sleepless night to give Jason a charm','string','Through a sleepless night Medea wavers between helping Jason and loyalty to her father, agrees at Chalciope''s plea to bring him a charm, contemplates poison in her shame, and turns back from death.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.05','hero.greek.medea','NARRATIVE_ACTION','hero.greek.jason',NULL,NULL,'At Hecate''s temple Medea gives Jason a charm made from the flower sprung from Prometheus''s ichor and instructs him in the midnight sacrifice to Hecate, the anointing that makes him proof against fire and bronze, and the stone to throw among the earthborn men.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.06','hero.greek.jason','NARRATIVE_ACTION',NULL,'yokes the fire-breathing bulls and destroys the earthborn men','string','Protected by Medea''s charm after his midnight sacrifice to Hecate, Jason yokes the fire-breathing bulls, ploughs the field of Ares, sows the serpent''s teeth and, throwing a great stone among the earthborn men, destroys them as they fight one another.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.07','hero.greek.medea','NARRATIVE_ACTION','artifact.greek.golden_fleece',NULL,NULL,'Fearing her father, Medea flees to the Argonauts, receives Jason''s oath of marriage, and lulls the sleepless serpent with song and a juniper sprig dipped in drugs so that Jason can take the golden fleece.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.08','hero.greek.jason','NARRATIVE_ACTION','hero.greek.apsyrtus',NULL,NULL,'When Apsyrtus blocks the Argonauts'' escape, Medea lures him with gifts to a night meeting at Artemis''s temple island, where Jason kills him from ambush, incurring Zeus''s wrath.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.09','deity.greek.circe','NARRATIVE_ACTION','hero.greek.medea',NULL,NULL,'Warned by the Argo''s speaking beam of Zeus''s wrath, the Argonauts reach Aeaea by the Eridanus and Rhodanus, where Circe purifies Jason and Medea of Apsyrtus''s blood with a suckling pig''s blood and then drives Medea from her hall.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.10','hero.greek.orpheus','NARRATIVE_ACTION','creature.greek.sirens',NULL,NULL,'Orpheus drowns the Sirens'' song with his lyre so that only Butes leaps overboard, rescued by Aphrodite, and Thetis and the Nereids toss the Argo from hand to hand past the Wandering Rocks.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.11','hero.greek.medea','NARRATIVE_ACTION','hero.greek.jason',NULL,NULL,'When the Colchians demand Medea of the Phaeacians, Queen Arete warns Jason of Alcinous''s judgment that only an unmarried maiden will be returned, and Jason and Medea are married that night in a sacred cave with the golden fleece spread on the bridal bed.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.12','artifact.greek.argo','NARRATIVE_ACTION',NULL,'is carried across the Libyan desert for twelve days','string','Stranded in the Libyan Syrtis, the Argonauts follow the riddle of the heroines of Libya and carry the Argo on their shoulders for twelve days to Lake Tritonis, drinking at the spring Heracles struck near the garden of the Hesperides.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.13','hero.greek.medea','NARRATIVE_ACTION','creature.greek.talos',NULL,NULL,'When the bronze giant Talos keeps the Argonauts from Crete with hurled rocks, Medea invokes the death-spirits and fixes him with her evil eye until he grazes the vein at his ankle and falls.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.argo_2.14','deity.greek.apollo','NARRATIVE_ACTION',NULL,'lights the sea with his golden bow and reveals Anaphe','string','In the Pall of Darkness after Crete, Apollo answers Jason''s prayer and lights the sea with his golden bow, revealing the island the Argonauts name Anaphe; Euphemus''s clod becomes Thera, and the heroes reach Pagasae.','v0340.argo_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Apollonius Rhodius, Argonautica (Seaton translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.01','event.norse.ragnarok','NARRATIVE_ACTION',NULL,'is preceded by the Fimbulwinter and three winters of kin-slaying war','string','Gylfaginning 51 says Ragnarök will be preceded by three winters of world-wide war in which kin kill kin, and by the Fimbulwinter, three winters together with no summer between.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.02','creature.norse.fenrir','NARRATIVE_ACTION',NULL,'breaks loose when every fetter breaks','string','In Gylfaginning 51 the wolf swallows the sun and the other seizes the moon, the stars vanish, the earth quakes so that every fetter breaks, and Fenrir runs free.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.03','artifact.norse.naglfar','NARRATIVE_ACTION',NULL,'is loosed in the flood and steered by Hrymr','string','In Gylfaginning 51 the sea surges ashore as the Midgard serpent writhes, and Naglfar, made of dead men''s nails, is loosed in the flood and steered by the giant Hrymr, while Fenrir advances with jaws from earth to sky.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.04','creature.norse.surtr','NARRATIVE_ACTION',NULL,'leads the sons of Muspell across the breaking Bifröst','string','In Gylfaginning 51 the sky splits and Surtr leads the sons of Muspell with fire before and behind him and a sword brighter than the sun; Bifröst breaks beneath them, and they gather with the giants and Hel''s host on the plain of Vígríðr.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.05','deity.norse.heimdall','NARRATIVE_ACTION','artifact.norse.gjallarhorn',NULL,NULL,'In Gylfaginning 51 Heimdall blows a mighty blast on the Gjallarhorn and wakes the gods, Odin rides to Mímir''s well for counsel, Yggdrasil trembles, and the Æsir and einherjar arm for battle.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.06','deity.norse.freyr','NARRATIVE_ACTION','creature.norse.surtr',NULL,NULL,'In Gylfaginning 51 Odin with golden helmet and Gungnir goes against Fenrir, Thor beside him must fight the Midgard serpent, and Freyr falls to Surtr for lack of the sword he gave to Skírnir.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.07','deity.norse.thor','NARRATIVE_ACTION','creature.norse.jormungandr',NULL,NULL,'In Gylfaginning 51 Garmr and Týr kill each other, and Thor kills the Midgard serpent but steps away only nine paces before falling dead from its poison.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.08','deity.norse.vidar','NARRATIVE_ACTION','creature.norse.fenrir',NULL,NULL,'In Gylfaginning 51 Fenrir swallows Odin, and Víðarr, wearing the shoe made of all the leather scraps ever cut, sets his foot in the wolf''s lower jaw and tears its mouth apart; Loki and Heimdall kill each other.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.09','creature.norse.surtr','NARRATIVE_ACTION',NULL,'flings fire over the earth and burns the whole world','string','In Gylfaginning 51 Surtr flings fire over the earth and burns the whole world, and Snorri quotes the Seeress''s Prophecy: the sun turns black, the earth sinks into the sea and the stars fall.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.10','event.norse.ragnarok','NARRATIVE_ACTION',NULL,'is followed by abodes of reward and punishment','string','Gylfaginning 52 describes the abodes after Ragnarök: Gimlé, Brimir and Sindri for the good, and Náströnd''s hall woven of serpents'' spines, where oath-breakers and murderers wade rivers of poison, and Hvergelmir, where Níðhöggr torments the dead.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.11','deity.norse.baldr','NARRATIVE_ACTION',NULL,'returns from Hel to the renewed world','string','In Gylfaginning 53 the earth rises green from the sea; Víðarr, Váli, Móði and Magni survive, Baldr and Höðr return from Hel, the gods find the golden chess pieces, Líf and Lífþrasir repeople the world, and the sun''s daughter drives her mother''s course.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.ragnarok.12','event.norse.ragnarok','NARRATIVE_ACTION',NULL,'ends Gangleri''s questioning as the hall vanishes','string','At the close of Gylfaginning (53–54) the speaker says no one can tell more of the world''s future, the hall vanishes around Gangleri leaving him on an open plain, and he returns to tell the stories.','v0340.ragnarok','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Gylfaginning',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.01','deity.norse.odin','NARRATIVE_ACTION',NULL,'leads his outlawed son Sigi to a new kingdom','string','When his son Sigi kills the thrall Breði in jealousy and is outlawed, Odin leads him out of the land and gives him warships, and Sigi wins the kingdom of Hunland.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.02','hero.norse.volsung','NARRATIVE_ACTION',NULL,'is born after six years and builds his hall round the Branstock','string','Born after six years in the womb of a mother who conceived by eating Odin''s apple brought by the wish-maiden Hljóð, Völsungr becomes king, marries Hljóð and builds his hall round the oak Branstock.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.03','hero.norse.sigmund','NARRATIVE_ACTION',NULL,'draws Odin''s sword from the Branstock','string','At Signý''s wedding feast a one-eyed stranger drives a sword into the Branstock; only Sigmundr can draw it, and his refusal to sell it to Siggeir for three times its weight in gold makes Siggeir his enemy.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.04','hero.norse.volsung','NARRATIVE_ACTION',NULL,'falls in Gautland keeping his vow never to flee','string','Warned by Signý of Siggeir''s treachery, Völsungr refuses to flee, keeping the vow he swore before his birth never to flee fire or iron, and falls in battle in Gautland while his ten sons are captured.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.05','hero.norse.sigmund','NARRATIVE_ACTION',NULL,'bites out the she-wolf''s tongue and escapes','string','After a she-wolf, said to be Siggeir''s mother, devours his nine brothers in the stocks on nine nights, Sigmundr, his face smeared with honey by Signý''s messenger, bites out the wolf''s tongue and escapes into the forest.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.06','hero.norse.signy','NARRATIVE_ACTION',NULL,'tests her sons by Siggeir and finds them unfit for vengeance','string','Testing her two sons by Siggeir for courage, Signý finds them afraid and has Sigmundr kill them, resolving that only a pure Völsung could be an avenger.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.07','hero.norse.sinfjotli','NARRATIVE_ACTION',NULL,'is born to Signý by Sigmundr and passes the test of courage','string','Born to Signý by Sigmundr after she exchanged shapes with a sorceress, Sinfjötli endures his mother''s test without flinching and kneads a venomous serpent into the bread Sigmundr sets him to make.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.08','hero.norse.sigmund','NARRATIVE_ACTION','hero.norse.sinfjotli',NULL,NULL,'Wearing enchanted wolf-skins with Sinfjötli, Sigmundr in anger bites him in the throat when he fights eleven men alone, then heals him with a leaf a raven brings, and they burn the skins.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.09','hero.norse.signy','NARRATIVE_ACTION',NULL,'returns into the burning hall to die with Siggeir','string','When Sigmundr and Sinfjötli, buried alive by Siggeir, cut through the mound''s dividing slab with the sword Signý throws in hidden in pork and burn Siggeir''s hall, Signý reveals Sinfjötli''s parentage and goes back into the fire to die with her husband.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.10','hero.norse.sinfjotli','NARRATIVE_ACTION',NULL,'is poisoned and carried off by a mysterious ferryman','string','Poisoned by Borghildr at her brother''s funeral feast after Sigmundr, drunk, tells him to strain the drink through his beard, Sinfjötli dies, and a mysterious ferryman takes his body and vanishes.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.11','deity.norse.odin','NARRATIVE_ACTION','hero.norse.sigmund',NULL,NULL,'In Sigmundr''s last battle against Lyngvi, a one-eyed man in a blue cloak holds up his spear against Sigmundr''s stroke and the sword breaks in two, and Sigmundr falls mortally wounded.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_1.12','hero.norse.sigmund','NARRATIVE_ACTION','weapon.norse.gram',NULL,NULL,'Dying, Sigmundr refuses healing because Odin has broken his sword and tells Hjördís to keep the shards for their unborn son, from which the sword Gram will be made; Hjördís is taken in by Álfr and bears Sigurðr.','v0340.vol_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.01','hero.norse.sigurd','NARRATIVE_ACTION','creature.norse.grani',NULL,NULL,'Fostered by the smith Reginn at King Hjálprekr''s court, Sigurðr chooses the grey horse Grani of Sleipnir''s kin by driving the herd into a river on the advice of a long-bearded old man, who is Odin.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.02','deity.norse.loki','NARRATIVE_ACTION',NULL,'kills Otr in otter shape and brings on the gods the otter-ransom','string','In Reginn''s tale Loki kills Otr, son of Hreiðmarr, in otter shape at Andvari''s falls with a stone, and Hreiðmarr seizes Odin, Loki and Hœnir until they agree to fill and cover the otter-skin with gold.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.03','being.norse.andvari','NARRATIVE_ACTION','artifact.norse.andvaranaut',NULL,NULL,'Caught as a pike in Rán''s net by Loki, the dwarf Andvari gives up his gold and the ring Andvaranautr, and curses both to be the death of everyone who owns them.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.04','creature.norse.fafnir','NARRATIVE_ACTION',NULL,'kills his father for the gold and becomes a dragon at Gnitaheiðr','string','After Odin covers the last whisker of the otter-skin with Andvaranautr and Loki repeats the curse, Fáfnir kills his father Hreiðmarr for the gold and becomes a dragon lying on it at Gnitaheiðr.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.05','weapon.norse.gram','NARRATIVE_ACTION',NULL,'is reforged from Sigmundr''s shards and cleaves the anvil','string','After two swords Reginn forges break on the anvil, he forges Gram from Sigmundr''s shards, and Sigurðr cleaves the anvil to its base with it and cuts a tuft of wool drifting in the river.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.06','hero.norse.sigurd','NARRATIVE_ACTION',NULL,'avenges Sigmundr on the sons of Hundingr','string','After Grípir foretells his fate, Sigurðr sails against the sons of Hundingr, takes aboard the stranger Hnikarr who stills the storm, and kills Lyngvi and his brothers, avenging his father.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.07','hero.norse.sigurd','NARRATIVE_ACTION','creature.norse.fafnir',NULL,NULL,'Advised by a long-bearded old man to dig trenches for the blood as well as the pit Reginn proposed, Sigurðr stabs Fáfnir from below under the left shoulder up to the hilt as the dragon crawls to the water.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.08','creature.norse.fafnir','NARRATIVE_ACTION','hero.norse.sigurd',NULL,NULL,'Dying, Fáfnir draws out Sigurðr''s name, warns him that the gold and the ring will be his bane and that Reginn will betray him, and answers his questions about the Norns and the last battle.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.09','hero.norse.sigurd','NARRATIVE_ACTION','being.norse.regin',NULL,NULL,'Tasting Fáfnir''s heart-blood as he roasts the heart, Sigurðr understands the nuthatches warning him of Reginn''s treachery, beheads Reginn with Gram, and loads the dragon''s hoard and the helm of terror onto Grani.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.10','hero.norse.brynhild','NARRATIVE_ACTION','hero.norse.sigurd',NULL,NULL,'On Hindarfjall Sigurðr cuts open the mail of a sleeping warrior in a shield-burg and wakes Brynhildr, whom Odin had pricked with a sleep-thorn for giving victory against his will, and who had vowed to wed only a man who knew no fear.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.11','hero.norse.brynhild','NARRATIVE_ACTION',NULL,'teaches Sigurðr the runes and swears oaths with him','string','Brynhildr gives Sigurðr a horn of mead and teaches him victory-runes, ale-runes, help-runes, sea-runes, limb-runes, speech-runes and mind-runes with counsels for life, and they swear oaths to each other.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_2.12','hero.norse.sigurd','NARRATIVE_ACTION','artifact.norse.andvaranaut',NULL,NULL,'At Hlymdalir Sigurðr sees Brynhildr through a tower window weaving his deeds in gold; though she foretells he will marry Guðrún, they renew their oaths and he gives her the ring Andvaranautr.','v0340.vol_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.01','hero.norse.brynhild','NARRATIVE_ACTION','hero.norse.gudrun',NULL,NULL,'Brynhildr interprets Guðrún''s dreams of a golden hawk and a golden hart, foretelling that she will marry Sigurðr through her mother''s guile, lose him through Brynhildr, then marry Atli and lose her brothers.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.02','hero.norse.sigurd','NARRATIVE_ACTION','hero.norse.gudrun',NULL,NULL,'At Gjúki''s court Queen Grímhildr gives Sigurðr a magic drink that makes him forget Brynhildr; he marries Guðrún and swears blood-brotherhood with Gunnarr and Högni under a strip of turf.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.03','hero.norse.gunnar','NARRATIVE_ACTION','hero.norse.sigurd',NULL,NULL,'When Gunnarr''s horse shies from the fire round Brynhildr''s hall and Grani will not move under him, he and Sigurðr exchange shapes by the craft Grímhildr taught them.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.04','hero.norse.sigurd','NARRATIVE_ACTION','hero.norse.brynhild',NULL,NULL,'In Gunnarr''s shape Sigurðr rides Grani through Brynhildr''s fire, claims her by her vow, lies three nights with the naked Gram between them, and takes from her the ring Andvaranautr, giving her another.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.05','hero.norse.sigurd','NARRATIVE_ACTION',NULL,'remembers his oaths to Brynhildr after her wedding to Gunnarr','string','At the end of Gunnarr and Brynhildr''s wedding feast Sigurðr remembers all his oaths to Brynhildr, but, married to Guðrún and bound to his sworn brother, he keeps silent.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.06','hero.norse.gudrun','NARRATIVE_ACTION','artifact.norse.andvaranaut',NULL,NULL,'When Brynhildr claims precedence while washing their hair in the Rhine, Guðrún reveals that Sigurðr, not Gunnarr, rode through the fire and shows her the ring Andvaranautr, and Brynhildr goes home pale and silent.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.07','hero.norse.brynhild','NARRATIVE_ACTION','hero.norse.gunnar',NULL,NULL,'Brynhildr lies silent for days, then reproaches Gunnarr for winning her by deceit, condemns Grímhildr''s drink of forgetfulness and curses the house of Gjúki as oath-breakers.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.08','hero.norse.sigurd','NARRATIVE_ACTION','hero.norse.brynhild',NULL,NULL,'Sigurðr tells Brynhildr he forgot her through the drink and offers to leave Guðrún for her, but she refuses to have two husbands in one hall, and his grief bursts the rings of his mail-coat as he leaves.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.09','hero.norse.gunnar','NARRATIVE_ACTION','hero.norse.sigurd',NULL,NULL,'Pressed by Brynhildr''s false charge, Gunnarr, bound with Högni by oaths of brotherhood, has their brother Guttormr, fed on wolf and serpent flesh, kill Sigurðr in his bed on the third morning.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.10','hero.norse.sigurd','NARRATIVE_ACTION','hero.norse.gudrun',NULL,NULL,'Mortally wounded, Sigurðr hurls Gram after Guttormr and cuts him in two, declares to Guðrún that he never wronged Gunnarr or betrayed their oath, and dies, while Brynhildr laughs at Guðrún''s wailing.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.11','hero.norse.gudrun','NARRATIVE_ACTION',NULL,'laments Sigurðr over his body','string','Guðrún sits dry-eyed by Sigurðr''s body until her sister lays his bloodied head in her lap, and then she weeps and laments that he stood among Gjúki''s sons like a tall leek above the grass.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.vol_3.12','hero.norse.brynhild','NARRATIVE_ACTION','hero.norse.sigurd',NULL,NULL,'Having foretold the fall of Gjúki''s house, Brynhildr stabs herself and asks to be burned on Sigurðr''s pyre with a naked sword between them as in their three nights, and they are burned together.','v0340.vol_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Völsunga saga (Morris and Magnússon translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.01','hero.irish.medb','NARRATIVE_ACTION','creature.irish.finnbennach',NULL,NULL,'In the pillow-talk at Cruachan, Medb and Ailill count their possessions and find them equal except for the White-horned Bull Finnbennach, born in Medb''s herd but gone over to Ailill''s, which Medb cannot match.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.02','hero.irish.medb','NARRATIVE_ACTION','creature.irish.donn_cuailnge',NULL,NULL,'Medb sends Mac Roth to borrow the Brown Bull of Cúailnge from Dáire mac Fiachna, who agrees until a drunken messenger boasts it would have been taken by force, whereupon Dáire refuses and Medb resolves to take it.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.03','hero.irish.medb','NARRATIVE_ACTION',NULL,'hears Fedelm''s prophecy of red ruin','string','Before the host sets out from Cruachan, the prophetess Fedelm tells Medb ''I see it crimson, I see it red'' and sings of a young warrior who will destroy her army alone.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.04','hero.irish.fergus_mac_roich','NARRATIVE_ACTION',NULL,'leads Medb''s host astray to give Ulster time','string','While the Ulstermen lie under Macha''s curse of debility and Cú Chulainn alone guards the border, Fergus leads Medb''s host astray to give Ulster time, and persuades Medb to scatter the outstanding Gailióin through the host instead of killing them.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.05','hero.irish.cu_chulainn','NARRATIVE_ACTION',NULL,'halts the host with the ogam withe and the forked branch','string','Cú Chulainn halts Medb''s host with an ogam-inscribed withe twisted with one hand, one foot and one eye, and with a four-pronged fork driven one-handed into a ford bearing the heads of four scouts, which only Fergus can pull out.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.06','hero.irish.fergus_mac_roich','NARRATIVE_ACTION','hero.irish.cu_chulainn',NULL,NULL,'Fergus tells Medb and Ailill how the boy Sétanta, not yet five, came alone to Emain Macha, warded off the hundred and fifty boys of the boy-troop and was taken in by King Conchobar.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.07','hero.irish.cu_chulainn','NARRATIVE_ACTION',NULL,'kills Culann''s hound and receives the name Cú Chulainn','string','As a boy Sétanta kills the smith Culann''s ferocious hound with his ball and a standing stone, offers to guard Culann''s house himself until a whelp is grown, and is named Cú Chulainn, ''the hound of Culann'', by the druid Cathbad.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.08','hero.irish.cu_chulainn','NARRATIVE_ACTION',NULL,'takes arms on the day of Cathbad''s prophecy','string','Hearing Cathbad say that whoever takes arms that day will be famous but short-lived, the boy Cú Chulainn takes Conchobar''s own arms and chariot, kills the three sons of Nechta Scéne, and is cooled from his battle-fury in three vats of water.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.09','hero.irish.cu_chulainn','NARRATIVE_ACTION',NULL,'fights champion after champion at the ford','string','Cú Chulainn agrees with Medb to fight one champion a day at the ford while the host advances only during the combat, drowns Fráech and kills many others, and gives way before Fergus on his promise to yield in return one day.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.10','deity.irish.morrigan','NARRATIVE_ACTION','hero.irish.cu_chulainn',NULL,NULL,'Refused by Cú Chulainn when she offers her love as a king''s daughter, the Morrígan attacks him as eel, wolf and heifer during his fight with Lóch and is wounded thrice, then is healed by his blessings as she gives him milk as an old woman.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.11','deity.irish.lugh','NARRATIVE_ACTION','hero.irish.cu_chulainn',NULL,NULL,'At Lerga, Lug mac Ethnenn comes from the síd unseen through the host, tells the wounded Cú Chulainn that he is his father, and heals him with herbs of the síd while he sleeps three days and nights.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.12','hero.irish.conchobar','NARRATIVE_ACTION',NULL,'loses his son Follomain with the boy-troop of Emain','string','While Cú Chulainn sleeps under Lugh''s care, the boy-troop of Emain led by Conchobar''s son Follomain attacks Medb''s host three times and is slain to the last boy.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_1.13','hero.irish.cu_chulainn','NARRATIVE_ACTION',NULL,'makes the Great Slaughter in his battle-distortion','string','To avenge the boy-troop, Cú Chulainn in his ríastrad, the monstrous battle-distortion, drives his scythed chariot round the host of the four provinces in the Great Slaughter on the plain of Muirthemne.','v0340.tain_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.01','hero.irish.medb','NARRATIVE_ACTION','hero.irish.ferdiad',NULL,NULL,'Medb forces Fer Diad, Cú Chulainn''s foster-brother and fellow pupil of Scáthach, to fight him by threatening him with poets'' satire and promising her daughter Finnabair, land and freedom from tribute.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.02','hero.irish.ferdiad','NARRATIVE_ACTION','hero.irish.cu_chulainn',NULL,NULL,'On the first day at the ford Fer Diad and Cú Chulainn fight with casting-weapons from morning to evening, then embrace, and that night share healing herbs and food, their horses in one paddock and their charioteers at one fire.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.03','hero.irish.cu_chulainn','NARRATIVE_ACTION','hero.irish.ferdiad',NULL,NULL,'On the second day Cú Chulainn and Fer Diad fight with heavy spears from their chariots and still exchange courtesies at night; on the third, with heavy swords, after which they part without embracing.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.04','hero.irish.cu_chulainn','NARRATIVE_ACTION','weapon.irish.gae_bulg',NULL,NULL,'On the fourth day at the ford, as Fer Diad''s sword pierces him, Cú Chulainn calls for the Gáe Bulga, casts it from between his toes through Fer Diad''s iron and stone, and Fer Diad dies in his arms.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.05','hero.irish.cu_chulainn','NARRATIVE_ACTION',NULL,'laments Fer Diad at the ford','string','Cú Chulainn carries the dead Fer Diad across the ford to the northern bank, faints beside him, and laments that all fighting before had been play and pleasure until he met Fer Diad.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.06','hero.irish.conchobar','NARRATIVE_ACTION',NULL,'rouses Ulster after Sualtam''s severed head cries out','string','When Sualtam, beheaded by the rim of his own shield as his horse wheels, still cries from the shield that Ulster''s men are slain, women carried off and cattle driven, Conchobar swears to restore them all and the Ulstermen rise from their debility.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.07','hero.irish.fergus_mac_roich','NARRATIVE_ACTION',NULL,'names the Ulster companies as Mac Roth describes them','string','As the risen Ulstermen march on the plain of Gárech, Mac Roth describes each approaching company to Medb and Ailill, and the exiled Fergus names their leaders.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.08','hero.irish.fergus_mac_roich','NARRATIVE_ACTION','weapon.irish.caladbolg',NULL,NULL,'In the battle of Gárech Fergus strikes Conchobar''s shield with Caladbolg until a warrior (in some versions Cormac Cond Longas) persuades him to turn his wrath on the hills, and he strikes the tops from three hills, the three Maela of Meath.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.09','hero.irish.fergus_mac_roich','NARRATIVE_ACTION','hero.irish.cu_chulainn',NULL,NULL,'Hearing Caladbolg strike Conchobar''s shield, Cú Chulainn bursts his bonds and calls on Fergus to keep his promise; Fergus retreats three steps, and his exiles and the men of Leinster and Munster leave the field.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.10','hero.irish.cu_chulainn','NARRATIVE_ACTION','hero.irish.medb',NULL,NULL,'With the host routed and the Brown Bull sent ahead to Connacht, Cú Chulainn finds Medb on her retreat, spares her because he will not kill a woman, and guards her until the host crosses Áth Luain.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.11','creature.irish.donn_cuailnge','NARRATIVE_ACTION','creature.irish.finnbennach',NULL,NULL,'Brought to Connacht, the Brown Bull of Cúailnge fights the White-horned Bull Finnbennach through a whole night across Ireland, trampling the judge Bricriu, and is seen at dawn with Finnbennach''s remains on its horns.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.tain_2.12','creature.irish.donn_cuailnge','NARRATIVE_ACTION',NULL,'dies on Druim Tairb when its heart breaks','string','Scattering Finnbennach''s remains across Ireland, giving names to places such as Áth Luain, the Brown Bull returns to Cúailnge and dies on Druim Tairb when its heart breaks, and peace is made for seven years.','v0340.tain_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Táin Bó Cúalnge, Book of Leinster recension (Dunn translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.01','hero.welsh.pwyll','NARRATIVE_ACTION','deity.welsh.arawn',NULL,NULL,'Hunting at Glyn Cuch, Pwyll drives off a pack of shining white red-eared hounds from their stag and is rebuked by their master, Arawn, king of Annwn, who asks him to rid him of his rival Hafgan in amends.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.02','hero.welsh.pwyll','NARRATIVE_ACTION','place.welsh.annwn',NULL,NULL,'In Arawn''s shape Pwyll rules Annwn for a year in all its splendour, and every night turns his back to Arawn''s queen and keeps faith with Arawn.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.03','hero.welsh.pwyll','NARRATIVE_ACTION',NULL,'kills Hafgan with a single blow and refuses a second','string','At the ford Pwyll, in Arawn''s shape, mortally wounds Hafgan with one blow and refuses to strike a second, so that Hafgan dies and his nobles submit, uniting Annwn under Arawn.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.04','deity.welsh.arawn','NARRATIVE_ACTION','hero.welsh.pwyll',NULL,NULL,'Returning to Annwn, Arawn learns from his queen that Pwyll never touched her in the whole year, and he and Pwyll become firm friends, Pwyll being called Head of Annwn.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.05','hero.welsh.pwyll','NARRATIVE_ACTION','hero.welsh.rhiannon',NULL,NULL,'Sitting on Gorsedd Arberth to see a wonder, Pwyll sees a lady on a white horse whom no rider can overtake though she rides slowly, until on the third day he calls on her to stop for the sake of the one she loves best.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.06','hero.welsh.rhiannon','NARRATIVE_ACTION','hero.welsh.pwyll',NULL,NULL,'Rhiannon, daughter of Hefeydd the Old, chooses Pwyll over her betrothed, but at their wedding feast Pwyll rashly grants a boon to Gwawl son of Clud, who claims the bride, and Rhiannon devises a plan with a little bag.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.07','hero.welsh.pwyll','NARRATIVE_ACTION',NULL,'traps Gwawl in the magic bag and wins Rhiannon','string','Disguised as a beggar, Pwyll asks Gwawl to fill Rhiannon''s magic bag with food, traps Gwawl in it when he treads the food down, and releases him in the first game of Badger in the Bag on condition he renounce Rhiannon.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.08','hero.welsh.rhiannon','NARRATIVE_ACTION','hero.welsh.pryderi',NULL,NULL,'When Rhiannon''s newborn son vanishes in the night, her six sleeping attendants smear her with a staghound pup''s blood and accuse her of devouring the child.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.09','hero.welsh.rhiannon','NARRATIVE_ACTION',NULL,'sits at the gate of Arberth telling her tale and carrying guests','string','Falsely accused, Rhiannon accepts the penance of sitting seven years by the horse-block at Arberth''s gate, telling her tale to strangers and offering to carry them on her back into the court.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.10','hero.welsh.pryderi','NARRATIVE_ACTION',NULL,'is found by Teyrnon at his stable door and named Gwri Golden-hair','string','Watching his mare on May Eve, Teyrnon cuts off a monstrous claw that seizes her foal through the window and finds an infant boy in satin at his door, whom he and his wife rear as Gwri Golden-hair.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.11','hero.welsh.pryderi','NARRATIVE_ACTION','hero.welsh.pwyll',NULL,NULL,'Seeing that the swiftly growing Gwri is the image of Pwyll and hearing of Rhiannon''s penance, Teyrnon and his wife resolve to return the boy to Arberth.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_1.12','hero.welsh.rhiannon','NARRATIVE_ACTION','hero.welsh.pryderi',NULL,NULL,'When Teyrnon brings the boy to Arberth and he is recognised as Pwyll''s image, Rhiannon says she is delivered of her anxiety (pryder), and the boy is named Pryderi; he later rules Dyfed and marries Cigfa.','v0340.mab_1','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.01','hero.welsh.bendigeidfran','NARRATIVE_ACTION','hero.welsh.matholwch',NULL,NULL,'From the rock of Harlech Bendigeidfran sees Matholwch''s thirteen ships come in peace to ask for Branwen, and agrees to the match, held at Aberffraw in tents since no house can hold him.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.02','hero.welsh.efnysien','NARRATIVE_ACTION','hero.welsh.matholwch',NULL,NULL,'Insulted that Branwen was married without his consent, Efnysien maims Matholwch''s horses, and Bendigeidfran makes amends with horses, a silver staff, a gold plate and the cauldron of rebirth.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.03','hero.welsh.matholwch','NARRATIVE_ACTION','hero.welsh.branwen',NULL,NULL,'Pressed by his people to avenge the insult of the horses, Matholwch drives Branwen from his chamber to cook for the court, where the butcher strikes her daily, and bans all ships to Britain for three years.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.04','hero.welsh.branwen','NARRATIVE_ACTION',NULL,'sends a starling to Britain with a letter of her sufferings','string','Branwen rears a starling at her kneading-trough, teaches it to speak and sends it to Britain with a letter under its wing, and Bendigeidfran, reading it, musters the hosts of the island for war on Ireland.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.05','hero.welsh.bendigeidfran','NARRATIVE_ACTION',NULL,'wades across the sea to Ireland','string','Bendigeidfran wades across the sea to Ireland with his musicians on his back, and Branwen interprets the swineherds'' vision: the forest is the ships'' masts, the mountain her brother, the ridge his nose and the lakes his eyes.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.06','hero.welsh.bendigeidfran','NARRATIVE_ACTION',NULL,'lies across the river as a bridge for his army','string','When the Irish break the bridge over the river, Bendigeidfran says ''He who is a chief, let him be a bridge'' and lies across it so that his host crosses over him; the Irish then offer the kingship to Gwern and build a house large enough to hold him.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.07','hero.welsh.efnysien','NARRATIVE_ACTION',NULL,'crushes the warriors hidden in the hundred bags','string','Entering the great house before the host, Efnysien asks what is in each of the hundred bags hung on its pillars, is told ''meal'', and crushes the head of the armed man hidden in each.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.08','hero.welsh.efnysien','NARRATIVE_ACTION',NULL,'throws Gwern into the fire','string','After the peace is made and the kingship given to Branwen''s son Gwern, Efnysien calls the child to him and throws him headlong into the fire, and war breaks out in the house as Bendigeidfran shields Branwen.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.09','hero.welsh.efnysien','NARRATIVE_ACTION','artifact.welsh.cauldron_of_rebirth',NULL,NULL,'Repenting as the Irish revive their dead in the cauldron of rebirth, Efnysien lies among the Irish dead, is thrown into the cauldron, and stretches himself until it bursts into four pieces and his own heart bursts.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.10','hero.welsh.bendigeidfran','NARRATIVE_ACTION',NULL,'bids the seven survivors carry his severed head to London','string','Wounded in the foot by a poisoned spear, Bendigeidfran bids the seven survivors cut off his head and carry it to the White Mount in London, foretelling seven years'' feasting at Harlech and eighty at Gwales in its company.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.11','hero.welsh.branwen','NARRATIVE_ACTION',NULL,'dies of a broken heart at Aber Alaw','string','Landing at Aber Alaw and seeing both Ireland and Britain, Branwen laments that two good islands were laid waste because of her, and her heart breaks; she is buried in a four-sided grave by the Alaw.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_2.12','hero.welsh.manawydan','NARRATIVE_ACTION',NULL,'feasts with the wondrous head at Harlech and Gwales','string','The seven survivors feast seven years at Harlech to the song of Rhiannon''s birds and eighty years at Gwales with the uncorrupted head, until Heilyn opens the door facing Cornwall, their grief returns, and they bury the head in London.','v0340.mab_2','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.01','hero.welsh.pryderi','NARRATIVE_ACTION','hero.welsh.manawydan',NULL,NULL,'Seeing Manawydan homeless after Caswallon''s usurpation, Pryderi gives him his mother Rhiannon in marriage and the rule of the seven cantrefs of Dyfed.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.02','hero.welsh.manawydan','NARRATIVE_ACTION',NULL,'finds Dyfed emptied by thunder and mist','string','As Manawydan, Rhiannon, Pryderi and Cigfa sit on Gorsedd Arberth, a peal of thunder and a mist leave Dyfed emptied of all people, houses and beasts but themselves.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.03','hero.welsh.manawydan','NARRATIVE_ACTION',NULL,'excels as saddler and shield-maker and avoids a fight','string','In England Manawydan and his companions make saddles at Hereford and then shields so well that the local craftsmen plot to kill them, and each time Manawydan restrains Pryderi from fighting and they move on.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.04','hero.welsh.manawydan','NARRATIVE_ACTION',NULL,'becomes one of the Three Golden Shoemakers','string','Making shoes with gilded buckles so fine that he is called one of the Three Golden Shoemakers of Britain, Manawydan again avoids a fight with jealous craftsmen and returns with his companions to empty Dyfed.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.05','hero.welsh.pryderi','NARRATIVE_ACTION',NULL,'enters the enchanted fortress after the white boar','string','Following a shining white boar that leads their hounds into a strange new fortress, Pryderi goes in after them against Manawydan''s warning that the fortress is the work of whoever enchanted the land.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.06','hero.welsh.rhiannon','NARRATIVE_ACTION','hero.welsh.pryderi',NULL,NULL,'Inside the fortress Pryderi and then Rhiannon take hold of a golden bowl hung by chains from the sky beside a fountain, stick fast and lose their speech, and vanish with the fortress in thunder and mist.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.07','hero.welsh.manawydan','NARRATIVE_ACTION',NULL,'swears to be a true companion to Cigfa and sows three crofts','string','Left alone with Pryderi''s wife Cigfa, Manawydan swears to be a true companion to her as to a daughter, makes shoes again in England, and returns to Dyfed with wheat to sow three crofts.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.08','hero.welsh.manawydan','NARRATIVE_ACTION',NULL,'watches mice carry off his wheat','string','Finding two of his three crofts of wheat stripped of every ear overnight, Manawydan watches the third and sees a countless host of mice climb the stalks and carry off the ears.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.09','hero.welsh.manawydan','NARRATIVE_ACTION',NULL,'catches a pregnant mouse and resolves to hang it','string','Manawydan catches a heavy, slow mouse in his glove and resolves to hang it despite Cigfa''s protest that it is unseemly for a man of his rank.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.10','hero.welsh.manawydan','NARRATIVE_ACTION',NULL,'refuses the scholar''s and priest''s ransoms for the mouse','string','As Manawydan sets up a gallows on Gorsedd Arberth to hang the mouse, a poor scholar offers a pound and a priest three pounds for its release, and he refuses both before a bishop arrives with his retinue.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.11','hero.welsh.manawydan','NARRATIVE_ACTION',NULL,'wins the release of Rhiannon, Pryderi and Dyfed as ransom for the mouse','string','Refusing ever greater ransoms, Manawydan makes the bishop — Llwyd son of Cil Coed — release Rhiannon and Pryderi and lift the enchantment on Dyfed, and learns that the mouse is Llwyd''s wife and the enchantment was vengeance for Gwawl and the Badger in the Bag.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_3.12','hero.welsh.rhiannon','NARRATIVE_ACTION',NULL,'is restored from captivity with the asses'' collars','string','Having sworn Llwyd to take no vengeance, Manawydan sees Rhiannon and Pryderi restored and the people and herds of Dyfed returned, learning that in captivity Pryderi wore the gate-knockers and Rhiannon the asses'' collars.','v0340.mab_3','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.01','hero.welsh.gwydion','NARRATIVE_ACTION','hero.welsh.pryderi',NULL,NULL,'To draw Math away from his footholder Goewin, whom Gilfaethwy desires, Gwydion comes to Pryderi''s court as a bard and exchanges illusory horses, hounds and shields made from fungus for Pryderi''s swine from Annwn.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.02','hero.welsh.gwydion','NARRATIVE_ACTION','hero.welsh.pryderi',NULL,NULL,'While Math is at war, Gilfaethwy violates Goewin; when Pryderi proposes single combat to spare their people, Gwydion kills him at Maen Tyriawg by strength and magic.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.03','hero.welsh.math','NARRATIVE_ACTION','hero.welsh.gwydion',NULL,NULL,'Learning of Goewin''s violation, Math marries her to spare her shame and with his wand turns Gilfaethwy and Gwydion into a pair of deer, then swine, then wolves for three years before restoring them.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.04','hero.welsh.arianrhod','NARRATIVE_ACTION',NULL,'drops two children as she steps over Math''s wand','string','Stepping over Math''s magic wand as a test of maidenhood, Arianrhod drops a yellow-haired boy, baptised as Dylan son of the Wave, and something small that Gwydion hides in a chest.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.05','hero.welsh.lleu','NARRATIVE_ACTION','hero.welsh.arianrhod',NULL,NULL,'When Arianrhod swears her son shall have no name but from her, Gwydion brings him disguised as shoemakers'' boy, and when the boy strikes a wren between sinew and bone she laughs at the fair one''s skilful hand, giving him the name Lleu Llaw Gyffes.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.06','hero.welsh.gwydion','NARRATIVE_ACTION','hero.welsh.arianrhod',NULL,NULL,'When Arianrhod swears Lleu shall bear no arms unless she arms him, Gwydion comes with him as bards, conjures an illusory fleet attacking Caer Arianrhod, and she arms Lleu herself.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.07','hero.welsh.blodeuedd','NARRATIVE_ACTION','hero.welsh.lleu',NULL,NULL,'When Arianrhod swears Lleu shall have no wife of the race now on earth, Math and Gwydion make Blodeuedd from the blossoms of oak, broom and meadowsweet, and she marries Lleu, who rules Dinoding from Mur Castell.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.08','hero.welsh.blodeuedd','NARRATIVE_ACTION',NULL,'falls in love with Gronw Pebr and plots against Lleu','string','While Lleu is away, Blodeuedd shelters Gronw Pebr, lord of Penllyn, after his hunt, falls in love with him, and plots with him to learn how Lleu may be killed.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.09','hero.welsh.lleu','NARRATIVE_ACTION',NULL,'is struck by Gronw''s spear and flies away as an eagle','string','Lleu tells Blodeuedd he can be slain only by a spear a year in the making, on a riverbank under a thatched roof with one foot on a bath and the other on a he-goat; when he shows her the posture, Gronw''s spear strikes him and he flies away as an eagle.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.10','hero.welsh.gwydion','NARRATIVE_ACTION','hero.welsh.lleu',NULL,NULL,'Following a sow to an oak where she feeds on flesh falling from an eagle, Gwydion sings three englynion that bring the eagle down to his knee and restores Lleu to human form with his wand.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.11','hero.welsh.gwydion','NARRATIVE_ACTION','hero.welsh.blodeuedd',NULL,NULL,'As Blodeuedd flees and her maidens drown in Llyn y Morwynion, Gwydion overtakes her and turns her into an owl that will never dare show itself by day and that all birds will mob.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z'),
('claim.v0340.mab_4.12','hero.welsh.lleu','NARRATIVE_ACTION',NULL,'kills Gronw Pebr with a spear through the stone','string','Refusing compensation, Lleu has Gronw Pebr stand where he himself stood when struck; Gronw shelters behind a stone, but Lleu''s spear pierces the stone and kills him, and the stone is called Llech Gronw.','v0340.mab_4','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Four Branches of the Mabinogi (Guest translation)',NULL,NULL,'2026-10-24T12:00:00Z');

