INSERT OR IGNORE INTO story_event_nodes(
    id,story_version_id,event_order,title_zh,title_en,summary_zh,summary_en,anchor_claim_id,event_entity_id,place_entity_id,location_kind,coordinate_policy,evidence_status,uncertainty_note,created_at
) VALUES
('storyevent.v0340.greek_library_2_4_perseus.1','storyver.greek.library_2_4_perseus',1,'铜屋里的公主','The princess in the bronze chamber','阿尔戈斯的国王阿克里西俄斯只有一个女儿，名叫达那厄。','Acrisius, king of Argos, had only a daughter, Danaë.','claim.v0340.perseus.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.2','storyver.greek.library_2_4_perseus',2,'漂流的木箱','The drifting chest','阿克里西俄斯命人造了一只大木箱，把达那厄和襁褓中的珀尔修斯一起关进箱子里，钉死箱盖，抛进了大海。','Acrisius had a great chest made, shut Danaë and the infant Perseus inside it and cast it into the sea, so that the sea, not his own hands, would be rid of them.','claim.v0340.perseus.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.3','storyver.greek.library_2_4_perseus',3,'国王的宴会','The king''s feast','塞里福斯的国王波吕得克忒斯是狄克堤斯的兄弟。','Polydectes, king of Seriphos and brother of Dictys, fell in love with Danaë, but with Perseus grown and always guarding her he could not have his way.','claim.v0340.perseus.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.4','storyver.greek.library_2_4_perseus',4,'格赖埃的眼睛','The eye of the grey sisters','珀尔修斯并不孤单，众神在暗中帮助他。','Perseus was not alone: Hermes and Athena came to guide him, and led him first to the daughters of Phorcus and Ceto — Enyo, Pephredo and Deino, sisters of the Gorgons, old women from their birth.','claim.v0340.perseus.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.5','storyver.greek.library_2_4_perseus',5,'仙女的礼物','The gifts of the nymphs','珀尔修斯找到了仙女们。','Perseus came to the nymphs, who kept three things: winged sandals, a wallet called the kibisis, and the cap of Hades.','claim.v0340.perseus.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.6','storyver.greek.library_2_4_perseus',6,'三个戈耳工','The three Gorgons','珀尔修斯飞到大洋河边，看见三个戈耳工正在熟睡。','At the stream of Ocean Perseus found the three Gorgons asleep: Stheno, Euryale and Medusa.','claim.v0340.perseus.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.7','storyver.greek.library_2_4_perseus',7,'美杜莎的头','Medusa''s head','珀尔修斯不敢直视美杜莎，就把目光转向手中那面光亮的青铜盾牌，从盾牌里看着美杜莎的倒影。','Not daring to look at Medusa, Perseus turned his eyes to his bright bronze shield and watched her reflection in it, while Athena guided his hand.','claim.v0340.perseus.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.8','storyver.greek.library_2_4_perseus',8,'海边的公主','The princess on the shore','珀尔修斯飞到了埃塞俄比亚，那里的国王是刻甫斯。','Perseus came to Ethiopia, ruled by Cepheus, and saw a beautiful girl chained to a rock by the sea: the king''s daughter Andromeda, waiting to be devoured by a sea monster.','claim.v0340.perseus.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.9','storyver.greek.library_2_4_perseus',9,'婚宴上的石像','Statues at the wedding','国王刻甫斯遵守誓言，为珀尔修斯和安德洛墨达举行婚礼。','Cepheus kept his oath and celebrated the wedding of Perseus and Andromeda.','claim.v0340.perseus.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.10','storyver.greek.library_2_4_perseus',10,'回到塞里福斯','Return to Seriphos','珀尔修斯带着安德洛墨达回到了塞里福斯岛。','Returning to Seriphos with Andromeda, Perseus found that in his absence Polydectes had used violence against his mother, and that Danaë and the kind Dictys had taken refuge at the altars, where no suppliant could be harmed.','claim.v0340.perseus.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.11','storyver.greek.library_2_4_perseus',11,'归还宝物','Returning the gifts','珀尔修斯的任务完成了，他不再需要那些神奇的宝物。','His task done, Perseus no longer needed the wonderful gifts.','claim.v0340.perseus.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_perseus.12','storyver.greek.library_2_4_perseus',12,'铁饼与神谕','The discus and the oracle','珀尔修斯带着达那厄和安德洛墨达，急忙赶往阿尔戈斯，想见见外祖父阿克里西俄斯。','Perseus hastened with Danaë and Andromeda to Argos to see Acrisius, but Acrisius, hearing of it and remembering the oracle, fled to Larissa in Pelasgiotis.','claim.v0340.perseus.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.1','storyver.greek.library_2_4_2_5_heracles_1',1,'宙斯的誓言','The oath of Zeus','珀尔修斯的孙子安菲特律翁娶了厄勒克特律翁的女儿阿尔克墨涅。','Amphitryon, grandson of Perseus, married Alcmena, daughter of Electryon.','claim.v0340.heracles_1.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.2','storyver.greek.library_2_4_2_5_heracles_1',2,'加长的夜晚','The lengthened night','安菲特律翁在塔福斯人那里打了胜仗。','Amphitryon conquered the Taphians.','claim.v0340.heracles_1.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.3','storyver.greek.library_2_4_2_5_heracles_1',3,'摇篮里的蛇','Serpents in the cradle','赫拉的嫉妒并没有因为夺走了王位而平息。','Hera''s jealousy was not satisfied.','claim.v0340.heracles_1.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.4','storyver.greek.library_2_4_2_5_heracles_1',4,'少年和他的老师','The boy and his teachers','赫拉克勒斯渐渐长大，安菲特律翁为他请来了全希腊最好的老师。','As Heracles grew, Amphitryon found him the best teachers in Greece: Amphitryon himself taught him to drive a chariot, Autolycus to wrestle, Eurytus to shoot with the bow, Castor to fight in arms, and Linus, brother of Orpheus, to play the lyre.','claim.v0340.heracles_1.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.5','storyver.greek.library_2_4_2_5_heracles_1',5,'喀泰戎山的狮子','The lion of Cithaeron','赫拉克勒斯十八岁的时候，喀泰戎山上出了一头凶猛的狮子，常常下山咬死安菲特律翁和邻国国王忒斯庇俄斯的牛羊。','When Heracles was eighteen, a lion on Mount Cithaeron was destroying the cattle of Amphitryon and of King Thespius, and Heracles set out to kill it.','claim.v0340.heracles_1.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.6','storyver.greek.library_2_4_2_5_heracles_1',6,'割掉耳朵的使者','The heralds without ears','明叶人的国王厄耳癸诺斯每年都向忒拜索取一百头牛作为贡赋，因为他的父亲曾被忒拜人杀死。','Erginus, king of the Minyans, exacted a yearly tribute of a hundred cattle from Thebes because the Thebans had killed his father.','claim.v0340.heracles_1.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.7','storyver.greek.library_2_4_2_5_heracles_1',7,'疯狂与神谕','Madness and the oracle','可是赫拉不会让他得到幸福。','But Hera would not let him be happy.','claim.v0340.heracles_1.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.8','storyver.greek.library_2_4_2_5_heracles_1',8,'涅墨亚的狮子','The Nemean lion','欧律斯透斯交给他的第一项任务，是取回涅墨亚狮子的皮。','The first labour Eurystheus imposed was to bring the skin of the Nemean lion, an invulnerable beast born of Typhon.','claim.v0340.heracles_1.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.9','storyver.greek.library_2_4_2_5_heracles_1',9,'九头蛇许德拉','The hydra of Lerna','第二项任务是杀死勒耳那沼泽里的水蛇许德拉。','The second labour was to kill the Lernaean hydra, which came out of the swamp to devour cattle and ravage the land.','claim.v0340.heracles_1.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.10','storyver.greek.library_2_4_2_5_heracles_1',10,'金角牝鹿','The golden-horned hind','第三项任务，是把刻律涅亚的牝鹿活着带回迈锡尼。','The third labour was to bring the Cerynitian hind alive to Mycenae.','claim.v0340.heracles_1.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.11','storyver.greek.library_2_4_2_5_heracles_1',11,'马人与野猪','The centaurs and the boar','第四项任务，是活捉厄律曼托斯山的野猪。','The fourth labour was to bring the Erymanthian boar alive.','claim.v0340.heracles_1.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.12','storyver.greek.library_2_4_2_5_heracles_1',12,'一天清扫牛圈','The cattle-yard cleansed in a day','第五项任务听起来最不像英雄的事业：欧律斯透斯命令他在一天之内，把厄利斯国王奥革阿斯的牛粪清扫干净。','The fifth labour sounded least heroic: to carry out the dung of the cattle of Augeas, king of Elis, in a single day.','claim.v0340.heracles_1.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_4_2_5_heracles_1.13','storyver.greek.library_2_4_2_5_heracles_1',13,'铜响板与怪鸟','Bronze castanets and the birds','第六项任务，是赶走斯廷法利斯湖的怪鸟。','The sixth labour was to chase away the Stymphalian birds.','claim.v0340.heracles_1.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.1','storyver.greek.library_2_5_heracles_2',1,'克里特的公牛','The Cretan bull','第七项任务，是把克里特的公牛带回来。','The seventh labour was to bring the Cretan bull.','claim.v0340.heracles_2.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.2','storyver.greek.library_2_5_heracles_2',2,'吃人的牝马','The man-eating mares','第八项任务，是把色雷斯国王狄俄墨得斯的牝马带到迈锡尼。','The eighth labour was to bring the mares of Diomedes the Thracian to Mycenae.','claim.v0340.heracles_2.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.3','storyver.greek.library_2_5_heracles_2',3,'亚马逊女王的腰带','The Amazon queen''s belt','第九项任务，是取回亚马逊女王希波吕忒的腰带。','The ninth labour was to bring the belt of Hippolyte, queen of the Amazons, a warlike nation by the river Thermodon whose women practised the arts of war.','claim.v0340.heracles_2.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.4','storyver.greek.library_2_5_heracles_2',4,'特洛伊的公主','The princess of Troy','从亚马逊人那里回来的路上，赫拉克勒斯在特洛伊靠岸。','On his way back from the Amazons Heracles put in at Troy, which was in distress.','claim.v0340.heracles_2.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.5','storyver.greek.library_2_5_heracles_2',5,'太阳神的金杯','The golden goblet of the Sun','第十项任务，是赶回革律翁的牛群。','The tenth labour was to fetch the cattle of Geryon from Erytheia, an island near Ocean in the far west.','claim.v0340.heracles_2.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.6','storyver.greek.library_2_5_heracles_2',6,'三身巨人','The triple-bodied giant','赫拉克勒斯在厄律提亚岛上的阿巴斯山过夜。','Heracles lodged on Mount Abas in Erytheia.','claim.v0340.heracles_2.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.7','storyver.greek.library_2_5_heracles_2',7,'赶牛回希腊','Driving the cattle home','赫拉克勒斯赶着牛群，穿过伊比利亚，走过高卢，来到了利古里亚。','Heracles drove the cattle through Iberia and Gaul into Liguria, where Ialebion and Dercynus, sons of Poseidon, tried to rob him and were killed, and through Tyrrhenia to Rhegium.','claim.v0340.heracles_2.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.8','storyver.greek.library_2_5_heracles_2',8,'海中老人与大地之子','The old man of the sea and the son of Earth','第十一项任务，是取回赫斯珀里得斯的金苹果。','The eleventh labour was to fetch the golden apples of the Hesperides — a wedding gift of Earth to Zeus — which grew by Atlas at the end of the world, guarded by an immortal dragon with a hundred heads and by the Hesperides.','claim.v0340.heracles_2.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.9','storyver.greek.library_2_5_heracles_2',9,'被解放的普罗米修斯','Prometheus set free','离开利比亚，赫拉克勒斯来到埃及。','From Libya Heracles went to Egypt, ruled by Busiris, a son of Poseidon, who sacrificed strangers on an altar of Zeus because of an oracle: after nine years of dearth, a seer from Cyprus had said the dearth would end if a stranger were sacrificed to Zeus every year, and Busiris began with the seer himself.','claim.v0340.heracles_2.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.10','storyver.greek.library_2_5_heracles_2',10,'扛起天空','Holding up the sky','赫拉克勒斯来到了世界的尽头，提坦神阿特拉斯就站在那里，用双肩扛着整个天空。','At the end of the world stood the Titan Atlas, holding up the sky on his shoulders.','claim.v0340.heracles_2.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.11','storyver.greek.library_2_5_heracles_2',11,'走向冥府','The road to Hades','最后一项任务，也是最可怕的一项：把冥府的看门狗刻耳柏洛斯带到人间来。','The last labour, and the most terrible, was to bring Cerberus up from Hades — a hound with three dogs'' heads, a dragon''s tail and the heads of all sorts of snakes on its back.','claim.v0340.heracles_2.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_5_heracles_2.12','storyver.greek.library_2_5_heracles_2',12,'冥府的看门狗','The hound of Hades','赫拉克勒斯来到冥王普路同面前，请求把刻耳柏洛斯带到人间去。','Heracles asked Pluto for Cerberus, and Pluto told him he might take it if he mastered it without the weapons he carried.','claim.v0340.heracles_2.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.1','storyver.greek.library_2_6_2_8_heracles_3',1,'射箭比赛','The archery contest','十二项任务完成以后，赫拉克勒斯回到了忒拜。','After the labours Heracles returned to Thebes and gave Megara to his nephew Iolaus; he wished to marry again.','claim.v0340.heracles_3.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.2','storyver.greek.library_2_6_2_8_heracles_3',2,'城墙上的推落','The fall from the walls','不久以后，有人从优卑亚岛偷走了欧律托斯的牛——偷牛的其实是有名的盗贼奥托吕科斯。','Not long after, cattle were stolen from Euboea by the thief Autolycus, and Eurytus supposed Heracles had done it.','claim.v0340.heracles_3.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.3','storyver.greek.library_2_6_2_8_heracles_3',3,'争夺三足鼎','The struggle for the tripod','为了治好这场病，赫拉克勒斯来到德尔斐，向阿波罗求问。','Seeking a cure, Heracles went to Delphi, but the Pythian priestess would not answer him.','claim.v0340.heracles_3.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.4','storyver.greek.library_2_6_2_8_heracles_3',4,'女王的奴仆','Servant of the queen','赫拉克勒斯成了吕底亚女王翁法勒的奴仆，替她清除国中的恶人。','As Omphale''s servant Heracles rid her land of wrongdoers.','claim.v0340.heracles_3.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.5','storyver.greek.library_2_6_2_8_heracles_3',5,'攻陷特洛伊','The sack of Troy','服役期满，赫拉克勒斯没有忘记当年对特洛伊国王拉俄墨冬发下的誓言。','His servitude over, Heracles sailed against Ilium with eighteen fifty-oared ships.','claim.v0340.heracles_3.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.6','storyver.greek.library_2_6_2_8_heracles_3',6,'巨人之战与奥林匹亚','The giants and Olympia','赫拉克勒斯从特洛伊返航时，赫拉又一次和他作对，向大海降下了猛烈的风暴。','As Heracles sailed from Troy, Hera sent grievous storms, at which Zeus in anger hung her from Olympus.','claim.v0340.heracles_3.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.7','storyver.greek.library_2_6_2_8_heracles_3',7,'与河神摔跤','Wrestling the river','赫拉克勒斯来到卡吕冬，向国王俄纽斯的女儿得伊阿尼拉求婚。','Heracles went to Calydon to woo Deianira, daughter of Oeneus.','claim.v0340.heracles_3.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.8','storyver.greek.library_2_6_2_8_heracles_3',8,'涅索斯的血','The blood of Nessus','赫拉克勒斯带着得伊阿尼拉，向特剌喀斯去投奔国王刻宇克斯，途中来到欧厄诺斯河边。','Going with Deianira to Ceyx at Trachis, Heracles came to the river Evenus, where the centaur Nessus — who, they say, had received the post from the gods for his righteousness — ferried passengers across for hire.','claim.v0340.heracles_3.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.9','storyver.greek.library_2_6_2_8_heracles_3',9,'攻陷俄卡利亚','The fall of Oechalia','在特剌喀斯，国王刻宇克斯接纳了赫拉克勒斯一家。','At Trachis Ceyx received Heracles and his family.','claim.v0340.heracles_3.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.10','storyver.greek.library_2_6_2_8_heracles_3',10,'致命的长袍','The deadly robe','得伊阿尼拉想起了涅索斯临死前的话。','Remembering Nessus''s words, Deianira supposed the blood was truly a love charm and smeared a tunic with it.','claim.v0340.heracles_3.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.11','storyver.greek.library_2_6_2_8_heracles_3',11,'俄塔山上的火','The fire on Oeta','赫拉克勒斯知道自己的生命快要走到尽头了。','Knowing his end was near, Heracles charged Hyllus, his elder son by Deianira, to marry Iole when he came of age.','claim.v0340.heracles_3.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_library_2_6_2_8_heracles_3.12','storyver.greek.library_2_6_2_8_heracles_3',12,'天上的婚礼与人间的子孙','A wedding in heaven, heirs on earth','赫拉克勒斯在天上获得了永生。','In heaven Heracles obtained immortality; reconciled at last with Hera, who had persecuted him from before his birth, he married her daughter Hebe, goddess of youth, and had by her two sons, Alexiares and Anicetus.','claim.v0340.heracles_3.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.1','storyver.greek.argonautica_seaton_1_2',1,'一只鞋的人','The man with one sandal','诗人先向阿波罗祈祷，然后讲起这个古老的故事。','The poet begins with a prayer to Apollo and tells the old story.','claim.v0340.argo_1.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.2','storyver.greek.argonautica_seaton_1_2',2,'阿尔戈号与英雄们','The Argo and her heroes','伊阿宋接受了任务。','Jason accepted.','claim.v0340.argo_1.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.3','storyver.greek.argonautica_seaton_1_2',3,'出航','Setting sail','出发的日子到了。','On the day of departure the people of Iolcus thronged the shore, and Jason''s mother Alcimede clung to him weeping like a girl who has lost her protector.','claim.v0340.argo_1.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.4','storyver.greek.argonautica_seaton_1_2',4,'女人的岛','The island of women','阿尔戈号来到了楞诺斯岛。','The Argo came to Lemnos, an island of women only.','claim.v0340.argo_1.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.5','storyver.greek.argonautica_seaton_1_2',5,'黑夜里的误战','Battle in the dark','离开楞诺斯，阿尔戈号穿过赫勒斯滂海峡，来到了普洛滂提斯海边的多利昂人的国家。','Leaving Lemnos the Argo passed the Hellespont to the land of the Doliones on the Propontis, whose young king Cyzicus, newly married, welcomed the heroes as an oracle had told him to.','claim.v0340.argo_1.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.6','storyver.greek.argonautica_seaton_1_2',6,'泉水中的少年','The boy in the spring','风平浪静了，英雄们比赛划桨，看谁最后一个累倒。','When the sea grew calm the heroes vied at rowing, and Heracles, the strongest, pulled until his oar broke.','claim.v0340.argo_1.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.7','storyver.greek.argonautica_seaton_1_2',7,'拳王阿密科斯','Amycus the boxer','第二天清晨，阿尔戈号来到了柏布律克斯人的国家。','Next morning the Argo came to the land of the Bebrycians, whose king Amycus, a son of Poseidon, had an outrageous law: no stranger might leave until he had boxed with him, and none had survived.','claim.v0340.argo_1.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.8','storyver.greek.argonautica_seaton_1_2',8,'盲眼先知与哈耳庇厄','The blind seer and the Harpies','阿尔戈号来到色雷斯海岸，英雄们遇见了盲眼的老先知菲纽斯。','On the Thracian coast the heroes found the blind old seer Phineus, punished by Zeus for revealing his designs to mortals: he was given long life but no sight, and the Harpies swooped from the clouds to snatch his food and befoul whatever they left.','claim.v0340.argo_1.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.9','storyver.greek.argonautica_seaton_1_2',9,'撞岩','The Clashing Rocks','从色雷斯出发，阿尔戈号驶向黑海的入口。','From Thrace the Argo made for the entrance of the Black Sea, where the Cyanean rocks, rooted in nothing, clashed together with a roar like thunder, crushing any ship that tried to pass.','claim.v0340.argo_1.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.10','storyver.greek.argonautica_seaton_1_2',10,'阿波罗的显现','The epiphany of Apollo','穿过撞岩以后，英雄们沿着黑海南岸向东航行。','Past the Rocks, the heroes coasted east along the Black Sea.','claim.v0340.argo_1.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.11','storyver.greek.argonautica_seaton_1_2',11,'战神岛的铁羽鸟','The birds of the island of Ares','阿尔戈号继续向东，经过了亚马逊人居住的忒耳摩冬河口，经过了以打铁为生、从不耕种的卡吕柏斯人的国家，来到了战神阿瑞斯的岛屿。','Sailing east past the mouth of the Thermodon, where the Amazons live, and the land of the Chalybes, who work iron and never plough, the Argo came to the island of Ares.','claim.v0340.argo_1.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_1_2.12','storyver.greek.argonautica_seaton_1_2',12,'驶入法细斯河','Into the river Phasis','阿尔戈号越过了黑海的东端。','The Argo reached the far end of the Black Sea.','claim.v0340.argo_1.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.1','storyver.greek.argonautica_seaton_3_4',1,'三位女神','Three goddesses','英雄们躲在法细斯河边的芦苇丛里，天上的赫拉和雅典娜却在为他们发愁：埃厄忒斯强大而残暴，单凭英雄们的勇气，是取不回金羊毛的。','While the heroes lay hidden in the reeds, Hera and Athena took counsel: Aeetes was too strong and cruel for courage alone to win the fleece.','claim.v0340.argo_2.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.2','storyver.greek.argonautica_seaton_3_4',2,'厄洛斯的箭','The arrow of Eros','伊阿宋带着佛里克索斯的儿子们和两位同伴，走进了埃厄忒斯的王宫。','Jason went into Aeetes''s palace with the sons of Phrixus and two comrades, Hera veiling them in mist through the city until they arrived.','claim.v0340.argo_2.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.3','storyver.greek.argonautica_seaton_3_4',3,'国王的考验','The king''s trial','宴席过后，埃厄忒斯问外乡人的来意。','After the feast Aeetes asked why they had come, and Argus explained that they sought the fleece at Pelias''s command and would serve the king against his enemies in return.','claim.v0340.argo_2.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.4','storyver.greek.argonautica_seaton_3_4',4,'美狄亚的不眠之夜','Medea''s sleepless night','那天夜里，美狄亚躺在床上，怎么也睡不着。','That night Medea lay sleepless, thinking of Jason''s face, his clothes, his voice, and of the fire-breathing bulls that would kill him tomorrow.','claim.v0340.argo_2.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.5','storyver.greek.argonautica_seaton_3_4',5,'赫卡忒神庙的相会','Meeting at Hecate''s temple','清晨，美狄亚梳妆打扮，带着侍女们乘马车来到了赫卡忒的神庙。','At dawn Medea went in her chariot with her maidens to the temple of Hecate, bringing a charm made from a flower that grew on the Caucasus from the ichor of Prometheus, dripping as the eagle tore him.','claim.v0340.argo_2.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.6','storyver.greek.argonautica_seaton_3_4',6,'喷火的公牛','The fire-breathing bulls','半夜，伊阿宋按照美狄亚的嘱咐，独自在河边沐浴，挖坑献祭。','At midnight Jason bathed and sacrificed as Medea had told him, and Hecate rose from the depths wreathed with serpents amid the barking of hellhounds and the glare of torches, while the marsh nymphs shrieked; he did not look back.','claim.v0340.argo_2.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.7','storyver.greek.argonautica_seaton_3_4',7,'盗取金羊毛','Taking the fleece','当天夜里，美狄亚知道父亲已经起了疑心，要对她和英雄们下毒手。','That night, knowing her father suspected her and plotted harm, Medea fled the palace barefoot with her casket of drugs and ran through the dark to the river, calling to the youngest son of Phrixus by the heroes'' fire.','claim.v0340.argo_2.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.8','storyver.greek.argonautica_seaton_3_4',8,'阿布绪耳托斯之死','The death of Apsyrtus','埃厄忒斯得知女儿和金羊毛都被带走了，怒不可遏，派出了大批船只追赶，领兵的是美狄亚的弟弟阿布绪耳托斯。','Aeetes, enraged, sent a great fleet after them under Medea''s brother Apsyrtus.','claim.v0340.argo_2.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.9','storyver.greek.argonautica_seaton_3_4',9,'会说话的船梁','The speaking beam','阿尔戈号继续航行，可是风暴一次又一次把它吹回原处。','The Argo sailed on, but storms drove her back again and again, until the Dodonian beam in her prow spoke with a human voice: Zeus was angry at the death of Apsyrtus, and they would never reach home unless Circe cleansed them of the blood.','claim.v0340.argo_2.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.10','storyver.greek.argonautica_seaton_3_4',10,'塞壬与漂浮岩','The Sirens and the Wandering Rocks','赫拉派彩虹女神伊里斯去请海中女神忒提斯——她是英雄珀琉斯的妻子——带着她的姐妹们来护送阿尔戈号。','Hera sent Iris to bid Thetis, wife of Peleus, bring her sister Nereids to escort the Argo.','claim.v0340.argo_2.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.11','storyver.greek.argonautica_seaton_3_4',11,'山洞里的婚礼','A wedding in the cave','阿尔戈号来到了费埃克斯人的岛屿德瑞帕涅，国王阿尔喀诺俄斯热情地款待了英雄们。','The Argo came to Drepane, island of the Phaeacians, where King Alcinous welcomed the heroes; but a great host of Colchians followed, demanding Medea on pain of war.','claim.v0340.argo_2.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.12','storyver.greek.argonautica_seaton_3_4',12,'扛着船穿越沙漠','Carrying the ship across the desert','阿尔戈号离开费埃克斯人，眼看希腊就在眼前，可是一场持续了九天九夜的北风，把他们吹到了利比亚的叙尔提斯海湾。','Leaving the Phaeacians, with Greece almost in sight, the Argo was driven by a north wind for nine days and nights into the Syrtis of Libya, shallow and choked with mud and weed, from which no ship returns.','claim.v0340.argo_2.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.13','storyver.greek.argonautica_seaton_3_4',13,'铜人塔罗斯','Talos the bronze man','在特里同神的指引下，阿尔戈号终于从特里托尼斯湖找到了通向大海的出口。','Guided by the god Triton, the Argo found her way from Lake Tritonis to the sea and made for Crete to take water.','claim.v0340.argo_2.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.greek_argonautica_seaton_3_4.14','storyver.greek.argonautica_seaton_3_4',14,'黑夜里的光明与归来','Light in the darkness, and home','离开克里特后，阿尔戈号在大海上遇到了一种可怕的黑暗，那黑暗被人们称作“裹尸布之夜”，没有星光，也没有月光，仿佛冥府的黑暗从地下涌了上来，英雄们不知道自己是在海上还是在冥河上漂流。','After Crete a terrible darkness fell on the sea — men call it the Pall of Darkness — with no star or moon, as if the black of Hades had risen from below, so that they knew not whether they drifted on the sea or the rivers of the dead.','claim.v0340.argo_2.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.1','storyver.norse.volsunga_morris_1_12',1,'奥丁之子西吉','Sigi, son of Odin','萨迦从奥丁的一个儿子讲起，他的名字叫西吉。','The saga begins with Sigi, a son of Odin.','claim.v0340.vol_1.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.2','storyver.norse.volsunga_morris_1_12',2,'苹果与六年的孕育','The apple and the six-year child','勒里尔国王和王后很久都没有孩子，他们为此十分忧愁，向众神祈求，希望能有一个儿子。','Rerir and his queen long had no child and prayed to the gods for a son.','claim.v0340.vol_1.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.3','storyver.norse.volsunga_morris_1_12',3,'橡树里的剑','The sword in the oak','高特兰的国王西格尔来向西格妮求婚。','Siggeir, king of Gautland, asked for Signý.','claim.v0340.vol_1.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.4','storyver.norse.volsunga_morris_1_12',4,'沃尔松格之死','The death of Völsungr','第二天，西格妮请求父亲让她早点离开，她说她不愿意跟西格尔走，她预感到这门亲事会带来灾难。','Next day Signý begged her father to let her stay, foreseeing disaster from the marriage, but Völsungr said a promise could not be broken without shame.','claim.v0340.vol_1.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.5','storyver.norse.volsunga_morris_1_12',5,'林中的母狼','The she-wolf in the forest','十个兄弟被锁在森林里的一根巨大的木枷上。','The ten brothers were set in a great stock in the forest.','claim.v0340.vol_1.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.6','storyver.norse.volsunga_morris_1_12',6,'西格妮的考验','Signý''s test','西格妮心中只有一个念头：为父亲和兄弟们报仇。','Signý thought only of vengeance.','claim.v0340.vol_1.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.7','storyver.norse.volsunga_morris_1_12',7,'辛菲奥特利','Sinfjötli','有一天，一个会魔法的女巫来到西格妮的住处。','One day a sorceress came to Signý, who asked to exchange shapes with her.','claim.v0340.vol_1.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.8','storyver.norse.volsunga_morris_1_12',8,'狼皮','The wolf-skins','西格蒙德觉得辛菲奥特利还太年轻，复仇之前应该让他经受更多的磨炼。','Thinking Sinfjötli too young, Sigmundr hardened him first; they roamed the forest through the summer killing men for plunder, Sigmundr still believing the boy was Siggeir''s son.','claim.v0340.vol_1.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.9','storyver.norse.volsunga_morris_1_12',9,'燃烧的大厅','The burning hall','复仇的时候到了。','The time for vengeance came.','claim.v0340.vol_1.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.10','storyver.norse.volsunga_morris_1_12',10,'博格希尔德的毒酒','Borghildr''s poison','大仇得报，西格蒙德回到了父亲的国家，赶走了趁他不在时占据王位的人，做了一个伟大的国王。','Vengeance done, Sigmundr returned to his father''s land, drove out the usurper and became a great king.','claim.v0340.vol_1.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.11','storyver.norse.volsunga_morris_1_12',11,'奥丁的长矛','Odin''s spear','博格希尔德被赶走，不久死去了。','Borghildr was driven out and soon died.','claim.v0340.vol_1.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_1_12.12','storyver.norse.volsunga_morris_1_12',12,'宝剑的碎片','The shards of the sword','夜里，约尔迪斯来到满是尸体的战场上，找到了垂死的西格蒙德，问他能不能医治。','That night Hjördís came to the field of the dead, found Sigmundr dying and asked if he could be healed.','claim.v0340.vol_1.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.1','storyver.norse.volsunga_morris_13_24',1,'少年与骏马','The boy and the horse','西古尔德在丹麦国王希亚尔普雷克的宫中长大，母亲约尔迪斯嫁给了国王的儿子阿尔夫，国王一家都非常爱护这个孩子。','Sigurðr grew up at the court of King Hjálprekr of Denmark, whose son Álfr married his mother Hjördís, and he was the most outstanding of youths, loved by all.','claim.v0340.vol_2.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.2','storyver.norse.volsunga_morris_13_24',2,'水獭的赎金','The otter''s ransom','雷金常常催促西古尔德去做一番大事业，有一天，他给西古尔德讲了一个故事。','Reginn often urged Sigurðr to great deeds, and one day told him a story.','claim.v0340.vol_2.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.3','storyver.norse.volsunga_morris_13_24',3,'安德瓦利的诅咒','Andvari''s curse','雷金接着讲：洛基到海神的妻子兰那里借来了她的网，来到安德瓦利瀑布。','Loki, Reginn went on, borrowed the net of Rán, the sea-god''s wife, and went to Andvari''s falls, where the dwarf Andvari lived as a pike.','claim.v0340.vol_2.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.4','storyver.norse.volsunga_morris_13_24',4,'变成恶龙的哥哥','The brother who became a dragon','洛基带着黄金回到赫雷德玛家里，众神先把水獭皮里面塞满了黄金，然后把它竖起来，用黄金把外面盖住。','Loki brought the gold, and the gods filled the otter-skin and set it up and covered it outside with gold.','claim.v0340.vol_2.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.5','storyver.norse.volsunga_morris_13_24',5,'重铸格拉姆','Gram reforged','雷金说：你若要杀死法夫纳，就需要一把好剑，我来为你打造。','Reginn said he would forge a sword for the slaying of Fáfnir.','claim.v0340.vol_2.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.6','storyver.norse.volsunga_morris_13_24',6,'为父报仇','Vengeance for his father','在去复仇之前，西古尔德去拜访了他的舅舅格里皮尔，格里皮尔能预知未来，把西古尔德一生的命运都告诉了他，萨迦只说他把将要发生的事情都讲了出来。','Before his vengeance Sigurðr visited his mother''s brother Grípir, who could see the future and told him all that would befall him.','claim.v0340.vol_2.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.7','storyver.norse.volsunga_morris_13_24',7,'坑中刺龙','The pit on Gnitaheiðr','西古尔德和雷金骑马来到格尼塔荒原，找到了法夫纳每天爬去喝水的路。','Sigurðr and Reginn rode to Gnitaheiðr and found the track by which Fáfnir crawled to water, down a cliff thirty fathoms high, says the saga.','claim.v0340.vol_2.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.8','storyver.norse.volsunga_morris_13_24',8,'恶龙的遗言','The dragon''s last words','法夫纳知道自己受了致命的伤，问：你是谁？','Mortally wounded, Fáfnir asked who he was, who his father and kin, that dared bear weapons against him.','claim.v0340.vol_2.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.9','storyver.norse.volsunga_morris_13_24',9,'龙心与鸟语','The dragon''s heart and the speech of birds','雷金回来了，他用刀割开法夫纳的心，喝了龙血，然后对西古尔德说：你杀死了我的哥哥，我也有罪，可是请你帮我一个忙：把这颗心烤熟给我吃。','Reginn came back, cut out Fáfnir''s heart and drank the blood, and asked Sigurðr to roast the heart for him.','claim.v0340.vol_2.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.10','storyver.norse.volsunga_morris_13_24',10,'盾牌堡里的女武神','The shield-maiden in the shield-burg','西古尔德骑着格拉尼向南走，来到了辛达山。','Sigurðr rode south to Hindarfjall, where a light shone like fire up to the sky.','claim.v0340.vol_2.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.11','storyver.norse.volsunga_morris_13_24',11,'卢恩与忠告','Runes and counsel','西古尔德请布伦希尔德教给他智慧，因为她知道世界上的一切事情。','Sigurðr asked Brynhildr to teach him wisdom, for she knew the tidings of all the worlds.','claim.v0340.vol_2.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_13_24.12','storyver.norse.volsunga_morris_13_24',12,'赫利姆谷的誓言','The vow at Hlymdalir','萨迦描写了西古尔德的模样：他的盾牌上画着一条深褐色的龙，铠甲是金色的，头发是褐色的，又长又美，胡子浓密，眼睛锐利，很少有人敢直视他的目光；他是那么高大，当他佩着格拉姆在长得很高的麦田里走过时，剑鞘的末端刚好碰到麦穗。','The saga describes Sigurðr: his shield painted with a dark-brown dragon, his armour golden, his hair brown, long and fair, his beard thick, his eyes so keen that few dared look into them, and so tall that when he walked with Gram through a full-grown field of rye the end of his scabbard just touched the ears.','claim.v0340.vol_2.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.1','storyver.norse.volsunga_morris_25_32',1,'古德伦的梦','Guðrún''s dream','在莱茵河以南，有一个名叫居基的国王，他有三个儿子：贡纳尔、霍格尼和年纪最小的古托姆，还有一个女儿古德伦，她是那里最美丽的少女。','South of the Rhine ruled King Gjúki, with three sons, Gunnarr, Högni and the youngest, Guttormr, and a daughter, Guðrún, the fairest of maidens; his queen Grímhildr was skilled in magic and hard of heart.','claim.v0340.vol_3.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.2','storyver.norse.volsunga_morris_25_32',2,'遗忘之酒','The drink of forgetfulness','不久，西古尔德骑着格拉尼，带着法夫纳的黄金，来到了居基王的宫廷。','Soon Sigurðr came to Gjúki''s court riding Grani with Fáfnir''s gold.','claim.v0340.vol_3.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.3','storyver.norse.volsunga_morris_25_32',3,'火墙','The wall of fire','格里姆希尔德又对儿子贡纳尔说：你应该娶一个妻子，最合适的就是布伦希尔德。','Grímhildr told Gunnarr he should take a wife, and the best match was Brynhildr.','claim.v0340.vol_3.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.4','storyver.norse.volsunga_morris_25_32',4,'火中的三夜','Three nights beyond the fire','西古尔德以贡纳尔的样子骑上了格拉尼，手握格拉姆，金色的马刺踢向马腹。','In Gunnarr''s shape Sigurðr mounted Grani with Gram in hand and golden spurs on his heels, and Grani leapt at the fire as soon as he felt the spurs; the earth shook and the flames rose to heaven, but Grani went through as if the fire died down before them.','claim.v0340.vol_3.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.5','storyver.norse.volsunga_morris_25_32',5,'婚礼与回忆','The wedding and the memory','布伦希尔德回到父亲那里，对赫米尔说：一个名叫贡纳尔的国王穿过了我的火墙，我只好嫁给他。','Brynhildr went to her father and told Heimir that a king called Gunnarr had ridden her fire and she must marry him — though she had told him that Sigurðr, to whom she had sworn at Hlymdalir, was the only man who could do it.','claim.v0340.vol_3.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.6','storyver.norse.volsunga_morris_25_32',6,'河边的争吵','The quarrel at the river','有一天，布伦希尔德和古德伦一起到莱茵河里洗头。','One day Brynhildr and Guðrún went to the Rhine to wash their hair, and Brynhildr waded further out.','claim.v0340.vol_3.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.7','storyver.norse.volsunga_morris_25_32',7,'布伦希尔德的悲痛','Brynhildr''s grief','布伦希尔德躺在床上，一连几天不吃不喝，也不说话。','Brynhildr lay in her bed for days without eating, drinking or speaking, and paid no heed to Gunnarr, Högni or Guðrún.','claim.v0340.vol_3.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.8','storyver.norse.volsunga_morris_25_32',8,'最后的谈话','The last conversation','西古尔德走进布伦希尔德的房间，对她说：醒醒吧，布伦希尔德，太阳照着整个宫殿，你睡得够久了，不要再悲伤了。','Sigurðr went in and bade Brynhildr wake, for the sun shone over the hall and she had slept long enough.','claim.v0340.vol_3.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.9','storyver.norse.volsunga_morris_25_32',9,'誓言与谋杀','The oath and the murder','布伦希尔德对贡纳尔说：你若想要我活下去，就必须杀死西古尔德和他的儿子，否则我就离开你，回到我的亲人那里去。','Brynhildr told Gunnarr that if he wished her to live, he must kill Sigurðr and his son, or she would leave him — claiming falsely that Sigurðr had betrayed him in those three nights beyond the fire.','claim.v0340.vol_3.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.10','storyver.norse.volsunga_morris_25_32',10,'西古尔德之死','The death of Sigurðr','西古尔德被剑刺穿，醒了过来。','Run through, Sigurðr woke, seized Gram beside the bed and hurled it after the fleeing Guttormr; it struck him in the back and cut him in two at the waist, so that his head and arms fell inside the chamber and his legs outside the door.','claim.v0340.vol_3.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.11','storyver.norse.volsunga_morris_25_32',11,'古德伦的哀哭','Guðrún''s lament','古德伦坐在西古尔德的尸体旁，一动不动，一滴眼泪也流不出来，人们都害怕她会因悲伤而死去。','Guðrún sat by Sigurðr''s body, motionless and dry-eyed, and they feared she would die of grief.','claim.v0340.vol_3.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_volsunga_morris_25_32.12','storyver.norse.volsunga_morris_25_32',12,'布伦希尔德的结局','The end of Brynhildr','布伦希尔德对贡纳尔说：我做了一个梦，梦见所有的人都会为这件事付出代价。','Brynhildr told Gunnarr she had dreamed that all would pay for the deed, and foretold the fate of Gjúki''s house: Guðrún would marry her brother Atli, Gunnarr and Högni would die at Atli''s hands, and Guðrún would avenge them.','claim.v0340.vol_3.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.1','storyver.irish.tain_dunn_1',1,'枕边的比较','The pillow-talk','在康诺特的克鲁亨王宫里，女王梅芙和国王艾利尔躺在床上，艾利尔说：俗话说得好，嫁给了好男人的女人是好女人。','In the royal palace of Cruachan in Connacht, Queen Medb and King Ailill lay in bed, and Ailill said it was true what they say, that a good man''s wife is well off — she was better off now than before she married him.','claim.v0340.tain_1.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.2','storyver.irish.tain_dunn_1',2,'借牛不成','The bull refused','梅芙叫来了信使马克·罗斯，问他是否知道爱尔兰哪里有一头能和白角公牛相比的公牛。','Medb asked her messenger Mac Roth whether there was a bull in Ireland to match the White-horned.','claim.v0340.tain_1.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.3','storyver.irish.tain_dunn_1',3,'我看见它是红色的','I see it crimson','梅芙召集了康诺特、伦斯特、芒斯特的大军，还有流亡在康诺特的阿尔斯特人，他们由弗格斯·马克·罗伊率领——弗格斯曾是阿尔斯特的国王，因为国王康胡巴尔背信弃义而离开了故乡。','Medb mustered the men of Connacht, Leinster and Munster, and the Ulster exiles in Connacht led by Fergus mac Róich, once king of Ulster, who had left his homeland because of King Conchobar''s treachery.','claim.v0340.tain_1.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.4','storyver.irish.tain_dunn_1',4,'阿尔斯特的衰弱','The weakness of Ulster','大军出发了。','The host set out.','claim.v0340.tain_1.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.5','storyver.irish.tain_dunn_1',5,'橡枝环与叉枝','The withe and the forked branch','库丘林在边界上发现了大军，他从一棵橡树上砍下一根树枝，只用一只手、一只脚、一只眼睛，把它弯成一个环，在上面刻上了欧甘文字，套在了一块立石上，作为警告：谁也不能越过这里，除非有人能用同样的方法——用一只手、一只脚、一只眼睛——做出一个同样的环。','Finding the host at the border, Cú Chulainn cut an oak sapling and, using only one hand, one foot and one eye, twisted it into a ring, cut an ogam inscription on it and set it round a standing stone as a warning: none must pass unless one of them made a ring the same way.','claim.v0340.tain_1.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.6','storyver.irish.tain_dunn_1',6,'五岁的男孩','The boy of five','艾利尔问：这个阿尔斯特人是谁？','Ailill asked who this Ulsterman was.','claim.v0340.tain_1.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.7','storyver.irish.tain_dunn_1',7,'库兰的猎犬','The hound of Culann','康诺特的科马克·孔德·隆加斯接着讲了另一件事。','Cormac Cond Longas then told another tale.','claim.v0340.tain_1.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.8','storyver.irish.tain_dunn_1',8,'拿起武器的那一天','The day of arms','接着，菲亚胡·马克·菲尔费巴讲了第三件事。','Fiachu mac Fir Febe told a third tale.','claim.v0340.tain_1.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.9','storyver.irish.tain_dunn_1',9,'浅滩上的决斗','Single combat at the ford','听完这些故事，梅芙和艾利尔明白了，他们面对的是一个可怕的敌人。','Medb and Ailill now knew what enemy they faced.','claim.v0340.tain_1.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.10','storyver.irish.tain_dunn_1',10,'莫莉甘','The Morrígan','一天，一位美丽的年轻女子来到库丘林面前，她穿着各种颜色的衣服，容貌非常秀美。','One day a young woman of great beauty in a many-coloured mantle came to Cú Chulainn, saying she was the daughter of King Búan and had come with her treasures and cattle because she loved him for his deeds.','claim.v0340.tain_1.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.11','storyver.irish.tain_dunn_1',11,'父亲鲁格','Lugh his father','日复一日的战斗之后，库丘林遍体鳞伤，疲惫不堪。','After day after day of combat Cú Chulainn was covered with wounds and worn out.','claim.v0340.tain_1.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.12','storyver.irish.tain_dunn_1',12,'少年队之死','The death of the boy-troop','就在库丘林沉睡的时候，艾温·马哈的少年队——一百五十个还没有受到衰弱诅咒的男孩——听说了库丘林独自守卫边界的事，决定前来帮助他。','While Cú Chulainn slept, the boy-troop of Emain — a hundred and fifty boys not yet under the curse of debility — heard that he guarded the border alone and came to help him, led by Follomain, son of King Conchobar, armed with their hurleys.','claim.v0340.tain_1.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_1.13','storyver.irish.tain_dunn_1',13,'大屠杀','The great slaughter','库丘林决心为少年们报仇。','Cú Chulainn resolved to avenge the boys.','claim.v0340.tain_1.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.1','storyver.irish.tain_dunn_2',1,'梅芙的诱惑','Medb''s offer','勇士们一个接一个死在浅滩上，梅芙和艾利尔商量：派谁去才能打败库丘林？','As champion after champion fell, Medb and Ailill agreed that only Fer Diad could overcome Cú Chulainn: his foster-brother, who had learned arms with him under the woman-warrior Scáthach in Alba, equal to him in every feat except the Gáe Bulga, which only Cú Chulainn had learned; and Fer Diad had a skin of horn that no weapon could pierce.','claim.v0340.tain_2.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.2','storyver.irish.tain_dunn_2',2,'第一天：投枪','The first day: casting-weapons','第二天清晨，费迪亚德来到浅滩，在浅滩北岸等候，库丘林从南岸来了。','At dawn Fer Diad waited on the north side of the ford and Cú Chulainn came to the south.','claim.v0340.tain_2.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.3','storyver.irish.tain_dunn_2',3,'第二天与第三天','The second and third days','第二天，轮到库丘林选择兵器，他说：今天我们用宽刃的重矛吧，坐在战车上作战，离得更近一些，好让我们早点分出胜负。','On the second day Cú Chulainn chose broad heavy spears, fighting from their chariots so that they might come to a decision sooner, and from morning to evening they pierced each other until birds could have flown in and out of their wounds.','claim.v0340.tain_2.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.4','storyver.irish.tain_dunn_2',4,'迦耶·博尔加','The Gáe Bulga','第四天清晨，费迪亚德知道这一天将决定一切，他穿上了最坚固的战甲，在腹部绑上一块大石头，以防备那可怕的迦耶·博尔加。','On the fourth morning Fer Diad, knowing this day would decide everything, put on his strongest armour and bound a great flat stone over his belly against the Gáe Bulga.','claim.v0340.tain_2.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.5','storyver.irish.tain_dunn_2',5,'库丘林的哀歌','Cú Chulainn''s lament','库丘林抱起费迪亚德，带着他的武器和铠甲，把他抬过浅滩，放在北岸。','Cú Chulainn lifted Fer Diad and carried him with his arms and armour across the ford to the north side; then he fainted beside him.','claim.v0340.tain_2.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.6','storyver.irish.tain_dunn_2',6,'苏阿尔塔姆的呼喊','Sualtam''s cry','库丘林的父亲苏阿尔塔姆听说儿子伤重，赶来看他。','Cú Chulainn''s father Sualtam came to his wounded son, who sent him to Emain Macha to rouse the Ulstermen: their men were being slain, their women carried off, their cattle driven away.','claim.v0340.tain_2.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.7','storyver.irish.tain_dunn_2',7,'阿尔斯特集结','The muster of Ulster','康胡巴尔派出使者，召集阿尔斯特各地的勇士们。','Conchobar sent messengers to summon the champions of Ulster, and from north and south, east and west the Ulstermen rose from their weakness, took up arms and gathered to the king at Slemain, then marched to the plain of Gárech where Medb''s host lay.','claim.v0340.tain_2.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.8','storyver.irish.tain_dunn_2',8,'三座山丘','The three hills','加雷赫和伊尔加雷赫的大战开始了。','The battle of Gárech and Irgárech began.','claim.v0340.tain_2.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.9','storyver.irish.tain_dunn_2',9,'弗格斯退让','Fergus gives way','库丘林听见了盾牌的呻吟声，问：是谁敢砍我的养父康胡巴尔的盾牌？','Cú Chulainn heard the groan and asked who dared strike the shield of his foster-father Conchobar; it was Fergus, he was told.','claim.v0340.tain_2.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.10','storyver.irish.tain_dunn_2',10,'梅芙被饶','Medb spared','到了傍晚，梅芙的大军已经溃不成军，只剩下一些残兵护送着她向西撤退。','By evening Medb''s host was routed, a remnant guarding her retreat westward.','claim.v0340.tain_2.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.11','storyver.irish.tain_dunn_2',11,'两头公牛的决斗','The fight of the bulls','褐色公牛被赶到了康诺特，它看见了一片陌生的、美丽的土地，发出了三声震耳欲聋的吼叫。','Driven into Connacht, the Brown Bull saw the fair strange land and bellowed three times.','claim.v0340.tain_2.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.irish_tain_dunn_2.12','storyver.irish.tain_dunn_2',12,'褐色公牛之死','The death of the Brown Bull','褐色公牛带着白角公牛的残骸一路向东奔跑，把对手的肢体一块块抛撒在爱尔兰各地。','The Brown Bull ran east with the White-horned''s remains, scattering its limbs across Ireland: at the ford of Athlone it dropped the loins, so the place was called Áth Luain, ''ford of the loins'', and at Trim the liver, and other parts elsewhere, each place taking its name from them.','claim.v0340.tain_2.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.1','storyver.welsh.mabinogi_guest_branch1',1,'格林·库赫的猎犬','The hounds at Glyn Cuch','达费德的王子皮威尔统治着七个坎特雷夫的土地。','Pwyll, prince of Dyfed, lord of seven cantrefs, was at Arberth when he wished to hunt and went to Glyn Cuch.','claim.v0340.mab_1.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.2','storyver.welsh.mabinogi_guest_branch1',2,'在彼世的一年','A year in the Otherworld','阿拉文说：我会把你变成我的样子，让你代替我在安农做一年的国王，我的王国里没有一个人会认出你，连我的妻子也不会；而我会变成你的样子，替你统治达费德。','Arawn said he would give Pwyll his own shape so that he could reign in Annwn for a year, and no one, not even Arawn''s wife, would know him; Arawn would take Pwyll''s shape and rule Dyfed.','claim.v0340.mab_1.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.3','storyver.welsh.mabinogi_guest_branch1',3,'浅滩上的一击','One blow at the ford','约定的那一天到了，皮威尔带着安农的贵族们来到浅滩，哈夫甘也带着他的人马来了。','On the appointed day Pwyll went to the ford with the nobles of Annwn, and Hafgan came with his host.','claim.v0340.mab_1.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.4','storyver.welsh.mabinogi_guest_branch1',4,'安农之主','Head of Annwn','一年期满，皮威尔来到格林·库赫，与阿拉文相见，两人各自恢复了原来的模样。','At the year''s end Pwyll met Arawn at Glyn Cuch and each took his own shape again.','claim.v0340.mab_1.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.5','storyver.welsh.mabinogi_guest_branch1',5,'土丘上的白马女子','The lady on the white horse','有一天，皮威尔在阿伯斯的王宫里举行宴会，宴罢之后，他走上了宫殿上方一座名叫戈尔塞斯·阿伯斯的土丘。','One day after a feast at Arberth, Pwyll went up the mound above the court called Gorsedd Arberth, of which it was said that any noble who sat on it would either receive wounds or see a wonder.','claim.v0340.mab_1.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.6','storyver.welsh.mabinogi_guest_branch1',6,'轻率的许诺','The rash promise','女子揭开面纱，皮威尔觉得自己从没见过这样美丽的面容。','She lifted her veil and he thought he had never seen a fairer face.','claim.v0340.mab_1.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.7','storyver.welsh.mabinogi_guest_branch1',7,'口袋里的獾','The badger in the bag','一年后，格瓦尔来赴他的婚宴。','A year later Gwawl came to his feast.','claim.v0340.mab_1.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.8','storyver.welsh.mabinogi_guest_branch1',8,'失踪的婴儿','The vanished child','皮威尔和里安农幸福地统治着达费德，可是过了两年，他们还没有孩子。','Pwyll and Rhiannon ruled Dyfed happily, but after two years they had no child, and in the third year the nobles urged Pwyll to take another wife who could bear him an heir.','claim.v0340.mab_1.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.9','storyver.welsh.mabinogi_guest_branch1',9,'里安农的惩罚','Rhiannon''s penance','消息传开了，贵族们要求皮威尔休掉里安农，皮威尔说：他们要我休妻，理由是她不能生育；可是她已经生了孩子，我不会休掉她。','The nobles demanded that Pwyll put her away.','claim.v0340.mab_1.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.10','storyver.welsh.mabinogi_guest_branch1',10,'泰尔农的马驹','Teyrnon''s foal','格温特·伊斯·科伊德的领主泰尔农·特威尔夫·里安特有一匹母马，是他国土上最美的马。','Teyrnon Twrf Liant, lord of Gwent Is Coed, had the fairest mare in his land; every May Eve she foaled, and no one knew what became of the foal.','claim.v0340.mab_1.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.11','storyver.welsh.mabinogi_guest_branch1',11,'长得像皮威尔的男孩','The boy who looked like Pwyll','这个孩子长得飞快，一岁时就像三岁的孩子一样会走路，两岁时像六岁的孩子一样强壮，不到四岁，就要和马夫们讨价还价，要他们让他把马牵到河边去饮水。','The boy grew wondrously: at one year he walked like a child of three, at two he was as big as a child of six, and before he was four he was bargaining with the grooms to let him lead the horses to water.','claim.v0340.mab_1.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch1.12','storyver.welsh.mabinogi_guest_branch1',12,'普雷德里','Pryderi','泰尔农带着男孩和两个骑士来到阿伯斯，看见里安农坐在宫门边的上马石旁。','Teyrnon came to Arberth with the boy and two knights and found Rhiannon by the horse-block.','claim.v0340.mab_1.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.1','storyver.welsh.mabinogi_guest_branch2',1,'哈勒赫的岩石上','On the rock of Harlech','李尔的儿子本迪盖德弗兰是这个岛屿——“强者之岛”不列颠——戴着伦敦王冠的国王。','Bendigeidfran son of Llŷr was crowned king of this island, the Island of the Mighty, with the crown of London.','claim.v0340.mab_2.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.2','storyver.welsh.mabinogi_guest_branch2',2,'受辱的马与复生之釜','The maimed horses and the cauldron','第二天，埃夫尼辛来到马索卢赫的马匹所在的地方，问这些是谁的马。','Next day Efnysien came upon Matholwch''s horses and, learning that Branwen had been given to their master without his consent, flew into a rage at the insult and maimed them, cutting off their lips, ears and tails and their eyelids.','claim.v0340.mab_2.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.3','storyver.welsh.mabinogi_guest_branch2',3,'厨房里的王后','The queen in the kitchen','马索卢赫带着布兰雯回到爱尔兰，人们热烈地欢迎她，她把胸针、戒指和珍宝分送给来见她的贵族和贵妇们，赢得了所有人的喜爱。','Matholwch brought Branwen to Ireland, where she was joyfully welcomed and won all hearts by giving brooches, rings and jewels to the nobles who came to see her.','claim.v0340.mab_2.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.4','storyver.welsh.mabinogi_guest_branch2',4,'八哥送信','The starling''s message','布兰雯在厨房的揉面槽边养了一只八哥，每天喂它，教它说话，告诉它她的哥哥是什么样子。','Branwen reared a starling on the edge of her kneading-trough, taught it words and told it what her brother was like.','claim.v0340.mab_2.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.5','storyver.welsh.mabinogi_guest_branch2',5,'海上的森林与山','A forest on the sea and a mountain','大军乘船驶向爱尔兰。','The host sailed for Ireland.','claim.v0340.mab_2.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.6','storyver.welsh.mabinogi_guest_branch2',6,'王者为桥','He who is a chief, let him be a bridge','不列颠的大军来到河边，发现桥已经被拆毁了，河里有一块磁石，任何船只和木筏都无法渡过。','At the river the bridge was broken and a lodestone in the riverbed let no ship or raft across.','claim.v0340.mab_2.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.7','storyver.welsh.mabinogi_guest_branch2',7,'百袋之屋','The house of the hundred bags','爱尔兰人在那座大房子里的一百根柱子上，每根都挂了一只皮袋，每只皮袋里都藏着一个全副武装的战士，准备在和谈时突然杀出来。','On each of the hundred pillars of the great house the Irish hung a leather bag with an armed man inside, ready to spring out during the peacemaking.','claim.v0340.mab_2.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.8','storyver.welsh.mabinogi_guest_branch2',8,'火中的格温','Gwern in the fire','两国的人在大房子里坐下来，举行和谈，王位交给了年幼的格温。','In the great house peace was made and the kingship given to the child Gwern.','claim.v0340.mab_2.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.9','storyver.welsh.mabinogi_guest_branch2',9,'破碎的釜','The broken cauldron','战斗开始了，爱尔兰人在火边点燃了复生之釜下面的火，把他们战死的人扔进釜里，第二天，那些死者都复活了，像从前一样勇猛地作战，只是不能说话。','In the fighting the Irish kindled a fire under the cauldron of rebirth and cast their dead into it, and next day they rose again to fight as fiercely as ever, though unable to speak; but the men of Britain, once slain, stayed dead.','claim.v0340.mab_2.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.10','storyver.welsh.mabinogi_guest_branch2',10,'受福之首','The blessed head','在这场大战中，本迪盖德弗兰的脚被一支毒矛刺伤了。','In the battle Bendigeidfran was wounded in the foot by a poisoned spear.','claim.v0340.mab_2.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.11','storyver.welsh.mabinogi_guest_branch2',11,'两个岛屿的悲伤','Grief for two islands','七个人带着本迪盖德弗兰的头和布兰雯，在安格尔西的阿劳河口上了岸。','The seven landed with the head and Branwen at Aber Alaw in Anglesey and sat down to rest.','claim.v0340.mab_2.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch2.12','storyver.welsh.mabinogi_guest_branch2',12,'哈勒赫与格瓦勒斯','Harlech and Gwales','七个人来到哈勒赫，坐下来宴饮。','At Harlech the seven sat down to feast, and three birds came and sang to them — the birds of Rhiannon — more sweetly than any song they had heard, and though the birds were far over the sea, they sounded as clear as if close by.','claim.v0340.mab_2.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.1','storyver.welsh.mabinogi_guest_branch3',1,'无家可归的王子','The prince without a home','七个人在伦敦埋葬了本迪盖德弗兰的头以后，马纳维丹望着伦敦城，望着他的同伴们，叹了一口气，说：哎呀，全能的上帝啊，我真是不幸，今晚除了我，每个人都有安身的地方。','After the seven had buried Bendigeidfran''s head in London, Manawydan looked at the city and his companions and sighed that everyone but he had a place to rest that night.','claim.v0340.mab_3.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.2','storyver.welsh.mabinogi_guest_branch3',2,'雷声与雾','Thunder and mist','一天，他们四人在阿伯斯的宫殿里宴饮，饭后，带着随从们走上了阿伯斯的土丘——就是当年皮威尔第一次看见里安农的地方。','One day after a feast at Arberth the four went up Gorsedd Arberth with their company — the mound where Pwyll had first seen Rhiannon.','claim.v0340.mab_3.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.3','storyver.welsh.mabinogi_guest_branch3',3,'马鞍匠与盾牌匠','Saddlers and shield-makers','马纳维丹说：我们不能再这样过下去了，我们到英格兰去，学一门手艺来谋生吧。','''We cannot go on like this,'' said Manawydan; ''let us go to England and take up a craft to earn our living.'' At Hereford they made saddles; Manawydan shaped them well and coloured them with blue enamel, as he had seen it done by Llasar Llaes Gyfnewid, and the townspeople bought no saddles but theirs.','claim.v0340.mab_3.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.4','storyver.welsh.mabinogi_guest_branch3',4,'金鞋匠','The golden shoemaker','他们来到第三个城市，普雷德里问：我们这次做什么手艺？','In a third town Pryderi asked what craft they would take up now.','claim.v0340.mab_3.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.5','storyver.welsh.mabinogi_guest_branch3',5,'白野猪与神秘的城堡','The white boar and the strange fortress','一天早晨，马纳维丹和普雷德里带着猎犬去打猎，猎犬们冲进一片灌木丛，又惊恐地退了回来，毛都竖了起来。','One morning Manawydan and Pryderi went hunting, and their hounds ran into a thicket and came back bristling in terror.','claim.v0340.mab_3.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.6','storyver.welsh.mabinogi_guest_branch3',6,'金碗与消失的城堡','The golden bowl and the vanished fortress','普雷德里走进城堡，里面没有人，没有房屋，也没有他的猎犬和野猪，只在城堡中央有一口泉水，泉水边有一块大理石板，石板上放着一只金碗，金碗用四根链子吊着，链子一直延伸到天上，看不见尽头。','Inside the fortress there was no man, no house, no hounds or boar — only a fountain in the middle with a marble slab beside it, and on the slab a golden bowl hung by four chains that went up into the sky out of sight.','claim.v0340.mab_3.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.7','storyver.welsh.mabinogi_guest_branch3',7,'马纳维丹与基格瓦','Manawydan and Cigfa','阿伯斯的宫殿里，只剩下马纳维丹和普雷德里的妻子基格瓦两个人了。','Only Manawydan and Pryderi''s wife Cigfa were left at Arberth.','claim.v0340.mab_3.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.8','storyver.welsh.mabinogi_guest_branch3',8,'被吃掉的麦田','The devoured fields','麦子成熟了，马纳维丹去看第一块麦田，说：明天我就来收割。','When the wheat was ripe Manawydan said he would reap the first croft next day; at dawn he found only bare straw, every ear cut off and carried away.','claim.v0340.mab_3.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.9','storyver.welsh.mabinogi_guest_branch3',9,'怀孕的老鼠','The pregnant mouse','那么多老鼠一下子都逃走了，只有一只老鼠跑得慢，因为它的身体又重又胖，落在了后面。','Of all the mice only one lagged behind, heavy and slow, and Manawydan caught it, put it in his glove, tied the mouth with a string, carried it home and hung the glove on a peg.','claim.v0340.mab_3.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.10','storyver.welsh.mabinogi_guest_branch3',10,'绞架与来客','The gallows and the visitors','第二天，马纳维丹带着老鼠来到阿伯斯的土丘上，在土丘的最高处插下两根叉形的木桩，准备在那里绞死老鼠。','Next day Manawydan took the mouse to the top of Gorsedd Arberth and set up two forked posts to hang it.','claim.v0340.mab_3.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.11','storyver.welsh.mabinogi_guest_branch3',11,'主教的赎金','The bishop''s ransom','主教问他在做什么，马纳维丹说：我在绞死一个小偷。','The bishop asked what he was doing and, seeing the mouse, said a man of his kind should not touch such a creature: let it go for seven pounds.','claim.v0340.mab_3.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch3.12','storyver.welsh.mabinogi_guest_branch3',12,'解除魔法','The enchantment lifted','马纳维丹说：我还要你发誓，以后永远不再对达费德施魔法，不再向普雷德里、里安农或我自己报复，为这件事报仇。','Manawydan demanded one more thing: Llwyd''s oath never again to enchant Dyfed nor take vengeance on Pryderi, Rhiannon or himself.','claim.v0340.mab_3.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.1','storyver.welsh.mabinogi_guest_branch4',1,'持足少女与普雷德里的猪','The footholder and Pryderi''s swine','马索努伊的儿子马斯是格温内斯的国王。','Math son of Mathonwy was king of Gwynedd, and he could not live unless his feet were in the lap of a maiden, except when war prevented it.','claim.v0340.mab_4.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.2','storyver.welsh.mabinogi_guest_branch4',2,'马恩·提里奥格的决斗','The duel at Maen Tyriawg','普雷德里发现自己被骗了，带着南方的大军向北追来，战争爆发了。','Discovering the deceit, Pryderi marched north with the men of the south, and war broke out; Math mustered Gwynedd against him.','claim.v0340.mab_4.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.3','storyver.welsh.mabinogi_guest_branch4',3,'变成野兽的兄弟','The brothers turned into beasts','马斯回到宫中，要把双脚放在戈尔文的膝上。','When Math returned and would put his feet in Goewin''s lap, she told him to seek another maiden, for she was one no longer, and told him what had been done.','claim.v0340.mab_4.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.4','storyver.welsh.mabinogi_guest_branch4',4,'魔杖的考验','The test of the wand','马斯需要一位新的持足少女，格威迪恩推荐了他的妹妹、多恩的女儿阿丽安萝德。','Math needed a new footholder, and Gwydion proposed his sister Arianrhod daughter of Dôn.','claim.v0340.mab_4.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.5','storyver.welsh.mabinogi_guest_branch4',5,'巧手的金发人','The fair one with the skilful hand','有一天早晨，格威迪恩在床上听见箱子里传出哭声，他打开箱子，看见一个小男孩伸出双臂。','One morning Gwydion heard a cry from the chest, opened it and found a little boy stretching out his arms.','claim.v0340.mab_4.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.6','storyver.welsh.mabinogi_guest_branch4',6,'幻象中的舰队','The phantom fleet','阿丽安萝德知道自己上当了，又下了第二个命运：除非我亲手给他武器，否则他永远不能拥有武器。','Arianrhod, tricked, laid a second destiny: he should never bear arms until she armed him herself.','claim.v0340.mab_4.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.7','storyver.welsh.mabinogi_guest_branch4',7,'花朵造成的妻子','The wife made of flowers','阿丽安萝德愤怒至极，下了第三个命运：他永远不能娶这世上任何一个种族的女子为妻。','Furious, Arianrhod laid a third destiny: he should never have a wife of the race that was now on the earth.','claim.v0340.mab_4.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.8','storyver.welsh.mabinogi_guest_branch4',8,'格罗努·佩布尔','Gronw Pebr','一天，勒伊去拜访马斯，布罗黛维德独自留在穆尔·卡斯泰尔。','One day while Lleu was visiting Math, Blodeuedd, walking in the court at Mur Castell, heard a horn and saw a weary stag pass with hounds and huntsmen after it: Gronw Pebr, lord of Penllyn, was hunting.','claim.v0340.mab_4.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.9','storyver.welsh.mabinogi_guest_branch4',9,'不在屋内也不在屋外','Neither in a house nor out of doors','那天晚上，布罗黛维德一言不发，勒伊问她为什么不高兴。','That night Blodeuedd was silent, and when Lleu asked why, she said she feared he would die before her.','claim.v0340.mab_4.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.10','storyver.welsh.mabinogi_guest_branch4',10,'橡树上的鹰','The eagle in the oak','格罗努占据了勒伊的宫殿和土地。','Gronw took Lleu''s court and lands.','claim.v0340.mab_4.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.11','storyver.welsh.mabinogi_guest_branch4',11,'猫头鹰','The owl','勒伊被带到卡耳·达瑟尔，格温内斯所有最好的医生都来为他治疗，到了年底，他终于恢复了健康。','Lleu was brought to Caer Dathyl, and all the best physicians of Gwynedd tended him until by the year''s end he was whole again.','claim.v0340.mab_4.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.welsh_mabinogi_guest_branch4.12','storyver.welsh.mabinogi_guest_branch4',12,'穿过石头的长矛','The spear through the stone','格罗努·佩布尔逃回了他的领地彭林，派使者去问勒伊，愿不愿意接受土地、金银作为赔偿。','Gronw Pebr fled to Penllyn and sent to ask whether Lleu would take land or gold and silver in compensation.','claim.v0340.mab_4.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.1','storyver.norse.ragnarok_gylf_long',1,'芬布尔之冬','The Fimbulwinter','在斯诺里的《欺骗古鲁菲》里，瑞典国王古鲁菲化名甘格勒里，来到众神的大厅，向三个坐在高座上的人提出各种问题。','In Snorri''s Gylfaginning, King Gylfi, calling himself Gangleri, questions three figures on high seats in the gods'' hall.','claim.v0340.ragnarok.01','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.2','storyver.norse.ragnarok_gylf_long',2,'狼吞日月','The wolves swallow sun and moon','接着，最可怕的事情发生了：一直追赶着太阳的狼吞下了太阳，人们会觉得这是巨大的灾难；另一只狼抓住了月亮，也造成了巨大的破坏。','Then will happen what seems the greatest disaster: the wolf will swallow the sun, and the other wolf will seize the moon and do great harm.','claim.v0340.ragnarok.02','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.3','storyver.norse.ragnarok_gylf_long',3,'死人指甲造的船','The ship of dead men''s nails','大海翻腾着涌上陆地，因为尘世巨蛇耶梦加得在巨人般的狂怒中翻滚着，爬上了岸。','The sea surges onto the land, because the Midgard serpent, Jörmungandr, writhes in giant rage and comes ashore — Loki''s child, cast by the gods into the ocean round the world, where it grew until it encircled the earth and bit its own tail.','claim.v0340.ragnarok.03','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.4','storyver.norse.ragnarok_gylf_long',4,'火焰之子','The sons of fire','在这一片喧嚣之中，天空裂开了，穆斯贝尔之子们从裂缝中骑马而来。','Amid the din the sky splits open and the sons of Muspell ride through.','claim.v0340.ragnarok.04','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.5','storyver.norse.ragnarok_gylf_long',5,'加拉尔号角','The Gjallarhorn','当这一切发生的时候，众神的守望者海姆达尔站了起来。','As all this happens, Heimdall, the gods'' watchman, stands up.','claim.v0340.ragnarok.05','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.6','storyver.norse.ragnarok_gylf_long',6,'奥丁、索尔与弗雷','Odin, Thor and Freyr','众神的队伍向维格利德平原进发，走在最前面的是奥丁。','The gods advance to Vígríðr, and Odin rides in front with a golden helmet, a beautiful mail-coat and his spear Gungnir, and goes against the wolf Fenrir.','claim.v0340.ragnarok.06','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.7','storyver.norse.ragnarok_gylf_long',7,'提尔与加姆，索尔与巨蛇','Týr and Garmr, Thor and the serpent','这时，被锁在格尼帕洞穴前的猎犬加姆也挣脱了锁链。','Then the hound Garmr, bound before the cave Gnipahellir, breaks loose — the worst of monsters, says Snorri.','claim.v0340.ragnarok.07','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.8','storyver.norse.ragnarok_gylf_long',8,'维达的鞋','Víðarr''s shoe','巨狼芬里尔张开大嘴，一口吞下了奥丁。','The wolf swallows Odin, and that is his death.','claim.v0340.ragnarok.08','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.9','storyver.norse.ragnarok_gylf_long',9,'苏尔特的火','Surtr''s fire','最后，苏尔特把火焰抛向大地，整个世界都燃烧起来。','Then Surtr flings fire over the earth and burns the whole world.','claim.v0340.ragnarok.09','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.10','storyver.norse.ragnarok_gylf_long',10,'天上的大厅与毒蛇的岸','Halls of reward, shore of serpents','高座上的人回答：那时会有许多住处，有的好，有的坏。','The answer comes: there will be many abodes, some good and some bad.','claim.v0340.ragnarok.10','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','学界常认为这一段的赏罚观念受到基督教影响；本篇只转述斯诺里的说法。','2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.11','storyver.norse.ragnarok_gylf_long',11,'重新升起的大地','The earth rises again','甘格勒里又问：那时还会有活着的神吗？','Gangleri asks whether any gods will live, and whether there will be earth and sky.','claim.v0340.ragnarok.11','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z'),
('storyevent.v0340.norse_ragnarok_gylf_long.12','storyver.norse.ragnarok_gylf_long',12,'消失的大厅','The vanishing hall','高座上的人最后说：如果你还能问得更远，我不知道你会从哪里得到答案，因为我从没听说过有谁能讲述世界更遥远的未来。','The figure on the high seat says at last that if Gangleri can ask further, he does not know where the answer will come from, for he has never heard anyone tell more of the world''s future; let him make good use of what he has learned.','claim.v0340.ragnarok.12','event.norse.ragnarok',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T12:00:00Z');

UPDATE stories SET reading_minutes=10,updated_at='2026-10-24T12:00:00Z' WHERE id='story.norse.ragnarok' AND reading_minutes<10;

UPDATE stories SET canonical_title='Ragnarök: the destruction and renewal of the world',editorial_note='长篇版本依据斯诺里《欺骗古鲁菲》第51–54章，斯诺里在其中大量引用《女巫的预言》等埃达诗；本篇只讲斯诺里的散文版本，不用流行文化补齐。原有纲要版本保留其缺口说明。',evidence_status='SOURCE_BACKED',summary_en='Snorri''s Gylfaginning tells the whole of Ragnarök: the Fimbulwinter, the wolves swallowing sun and moon, the breaking of every fetter, the last battle of gods and giants on the plain of Vígríðr, the deaths of Odin, Thor, Freyr, Týr and Heimdall, and Surtr''s fire burning the world; then the earth rises green from the sea and surviving gods and two humans begin a new world. The earlier three-part outline is kept; the long version follows chapters 51–54 section by section.',summary_zh='斯诺里的《欺骗古鲁菲》讲述了诸神黄昏的全过程：芬布尔之冬、狼吞日月、锁链断裂、诸神与巨人在维格利德平原决战、奥丁、索尔、弗雷、提尔与海姆达尔相继战死，苏尔特的火焰烧毁了整个世界；之后大地从海中重新升起，幸存的众神与两个人类开始了新的世界。原有的三段纲要版本保留，长篇版本按第51–54章逐段讲述。',title_zh='诸神黄昏：世界的毁灭与重生',updated_at='2026-10-24T12:00:00Z' WHERE id='story.norse.ragnarok';



INSERT OR IGNORE INTO story_series(
    id,title_zh,title_en,work_entity_id,primary_source_id,primary_civilization_id,description_zh,description_en,selection_note,featured_order,created_at,updated_at
) VALUES
('series.greek.heroes_library','希腊英雄连载','Greek heroes (series)','text.greek.apollodorus_library','source.greek.apollodorus.library.topostext','civ.greek','按阿波罗多洛斯《书库》第二卷的顺序连读四部：珀尔修斯，以及他的后代赫拉克勒斯从出生、十二项任务到火葬堆上升天，共四十九章。','Four parts read in the order of Book II of Apollodorus''s Library: Perseus, and his descendant Heracles from birth through the twelve labours to the pyre on Oeta — forty-nine chapters in all.','四部按顺序覆盖《书库》2.4.1–2.8.1，只在第四部内略去2.7.4（已在该部注明）；赫拉克勒斯参加阿尔戈远航的部分见“阿尔戈英雄连载”。',4,'2026-10-24T12:00:00Z','2026-10-24T12:00:00Z'),
('series.greek.argonautica','阿尔戈英雄连载','The Argonauts (series)','text.greek.argonautica','source.greek.argonautica_seaton.gutenberg','civ.greek','按西顿英译阿波罗尼俄斯《阿尔戈英雄纪》的四卷连读上下两部：上部远航（第一至二卷），下部金羊毛与归航（第三至四卷），共二十六章。','Seaton''s translation of Apollonius''s Argonautica read in two parts across all four books: the outward voyage (Books I–II) and the fleece and the return (Books III–IV) — twenty-six chapters in all.','两部覆盖全部四卷，没有跳过的卷；美狄亚后来在科林斯的故事出自欧里庇得斯等其他作家，不在本诗中。',5,'2026-10-24T12:00:00Z','2026-10-24T12:00:00Z'),
('series.norse.gylfaginning_end','诸神的黄昏连载','The twilight of the gods (series)','text.norse.gylfaginning','source.norse.prose_edda.vsnr','civ.norse','按斯诺里《欺骗古鲁菲》最后几章的顺序连读两部：巴德尔之死与洛基受罚（第49–50章），诸神黄昏、新世界与古鲁菲的幻境消失（第51–54章），共二十五章。','The last chapters of Snorri''s Gylfaginning read in two parts: the death of Baldr and the binding of Loki (chapters 49–50), and Ragnarök, the new world and the vanishing of the hall around Gylfi (chapters 51–54) — twenty-five chapters in all.','两部连续覆盖《欺骗古鲁菲》第49–54章；两个故事原有的短版本保留，系列打开的是长篇版本。',6,'2026-10-24T12:00:00Z','2026-10-24T12:00:00Z'),
('series.norse.volsunga','沃尔松格萨迦连载','The Saga of the Völsungs (series)','text.norse.volsunga_saga','source.norse.volsunga_morris.gutenberg','civ.norse','按莫里斯与马格努松英译《沃尔松格萨迦》的章节连读三部：西格蒙德（第1–13章）、屠龙者西古尔德（第13–24章）、西古尔德与布伦希尔德（第25–32章），共三十六章。','The Morris and Magnússon translation of the Völsunga saga read in three parts: Sigmundr (chapters 1–13), Sigurðr the dragon-slayer (13–24) and Sigurðr and Brynhildr (25–32) — thirty-six chapters in all.','三部连续覆盖萨迦第1–32章（第13章西古尔德出生横跨前两部）；第33–43章古德伦与阿特利、斯万希尔德的故事本系列暂未收录。',7,'2026-10-24T12:00:00Z','2026-10-24T12:00:00Z'),
('series.irish.tain','夺牛长征记连载','The Cattle Raid of Cooley (series)','text.irish.tain_bo_cuailnge','source.irish.tain_dunn.gutenberg','civ.irish','按邓恩英译莱因斯特书本《夺牛长征记》的情节顺序连读上下两部：库丘林守浅滩，费迪亚德与公牛之战，共二十五章。','Dunn''s translation of the Book of Leinster Táin read in two parts: Cú Chulainn at the fords, and Fer Diad and the battle of the bulls — twenty-five chapters in all.','两部覆盖全书的主要情节，众多单打独斗的对手和勇士名录只择要讲述；《阿尔斯特人的衰弱》等前传故事不在本系列中。',8,'2026-10-24T12:00:00Z','2026-10-24T12:00:00Z'),
('series.welsh.mabinogi','马比诺吉昂四支连载','The Four Branches of the Mabinogi (series)','text.welsh.four_branches','source.welsh.mabinogion_guest.gutenberg','civ.welsh','按格斯特夫人英译连读《马比诺吉昂》的四支：皮威尔、布兰雯、马纳维丹、马斯，普雷德里贯穿四支，共四十八章。','Lady Charlotte Guest''s translation of the Four Branches of the Mabinogi read in order — Pwyll, Branwen, Manawydan and Math, with Pryderi running through all four — forty-eight chapters in all.','四支全部收录，没有跳过的部分；格斯特译本中《马比诺吉昂》的其他故事（如《库尔赫奇与奥尔温》）不属于四支，不在本系列中。',9,'2026-10-24T12:00:00Z','2026-10-24T12:00:00Z');

